export const travelLearningQuotationRows: readonly string[] = [
  '{"definitionId":"visited-yosemite","slot":1,"id":"historic-quotation/q-1680707abc12407e2eb574e69854338c","text":"Afford all an unfettered start and a fair chance in the race of life.","person":"Abraham Lincoln","personWikipediaUrl":"https://en.wikipedia.org/wiki/Abraham_Lincoln","sourceTitle":"The Lincoln Year Book: Axioms and Aphorisms from the Great Emancipator","sourceUrl":"https://www.gutenberg.org/cache/epub/39204/pg39204.txt","sourceSha256":"1b6a3cb3664183e06d932e706117f3ca6721875c9564315ed22fe81897e3b4a2"}',
  '{"definitionId":"visited-yosemite","slot":2,"id":"historic-quotation/q-3e21fea2b4084afd1c940f35ca85d204","text":"Advantages that are dearly bought are doubtful blessings.","person":"Aesop","personWikipediaUrl":"https://en.wikipedia.org/wiki/Aesop","sourceTitle":"Aesop’s Fables: A New Translation (translated by V. S. Vernon Jones)","sourceUrl":"https://www.gutenberg.org/cache/epub/11339/pg11339.txt","sourceSha256":"0a2e7b971b00b76164071563e7e4bfa9cf962118ef67db9259020fc7c3b83602"}',
  '{"definitionId":"visited-acadia","slot":1,"id":"historic-quotation/q-8fbdd3309405e422b0fa7826603f7093","text":"\'Tis with our judgments as our watches; none Go just alike, yet each believes his own.","person":"Alexander Pope","personWikipediaUrl":"https://en.wikipedia.org/wiki/Alexander_Pope","sourceTitle":"Many Thoughts of Many Minds","sourceUrl":"https://www.gutenberg.org/cache/epub/17112/pg17112.txt","sourceSha256":"54ff4ba19eb9dd7b367d8f9893dd07fad81e5ce8b71bd5db5b38676c68221c21"}',
  '{"definitionId":"visited-acadia","slot":2,"id":"historic-quotation/q-bf2bcd6226a50a83dd9e4baec0b93e63","text":"Knowledge comes but wisdom lingers.","person":"Alfred, Lord Tennyson","personWikipediaUrl":"https://en.wikipedia.org/wiki/Alfred,_Lord_Tennyson","sourceTitle":"Pearls of Thought","sourceUrl":"https://www.gutenberg.org/cache/epub/26604/pg26604.txt","sourceSha256":"bd029a4490008a4ee6ad5738df5ba723c2ba850092f9e9042b32e0fe5540a2b6"}',
  '{"definitionId":"visited-arches","slot":1,"id":"historic-quotation/q-30bc0c129dde0fa33f8e4f3033df4d7d","text":"It is easier to carry the world in one\'s thoughts than on one\'s shoulders.","person":"Amos Bronson Alcott","personWikipediaUrl":"https://en.wikipedia.org/wiki/Amos_Bronson_Alcott","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-arches","slot":2,"id":"historic-quotation/q-37dfa528e583be225f3963cf322daa80","text":"The end of labour is to gain leisure.","person":"Aristotle","personWikipediaUrl":"https://en.wikipedia.org/wiki/Aristotle","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-badlands","slot":1,"id":"historic-quotation/q-82649a68a410ac28f5b486e6a03d7ecb","text":"Experience is a text to which reflection and knowledge supply the commentary.","person":"Arthur Schopenhauer","personWikipediaUrl":"https://en.wikipedia.org/wiki/Arthur_Schopenhauer","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-badlands","slot":2,"id":"historic-quotation/q-f2fd6530393fd15dee872e4d62cb2b55","text":"The dignity of truth is lost with much protesting.","person":"Ben Jonson","personWikipediaUrl":"https://en.wikipedia.org/wiki/Ben_Jonson","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-big-bend","slot":1,"id":"historic-quotation/q-e23e99c3a2574e1401b06273e6ec7b6d","text":"Circumstances are beyond the control of man, but his conduct is in his own power.","person":"Benjamin Disraeli","personWikipediaUrl":"https://en.wikipedia.org/wiki/Benjamin_Disraeli","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-big-bend","slot":2,"id":"historic-quotation/q-d67d3ee9dbe3cb002b8e8ccfc83be12b","text":"A Change of Fortune hurts a wise Man no more than a Change of the Moon.","person":"Benjamin Franklin","personWikipediaUrl":"https://en.wikipedia.org/wiki/Benjamin_Franklin","sourceTitle":"The Prefaces, Proverbs, and Poems of Benjamin Franklin","sourceUrl":"https://archive.org/download/prefacesproverbs00franrich/prefacesproverbs00franrich_djvu.txt","sourceSha256":"715b4de9f83af6844e62aeb157828c60ce662982a7b7e66ff2106cca2eb51858"}',
  '{"definitionId":"visited-biscayne","slot":1,"id":"historic-quotation/q-919001c10789c9e793f1747513675b13","text":"The constant man loses not his virtue in misfortune. A torch may point towards the ground, but its flame will still point upwards.","person":"Bhartrihari","personWikipediaUrl":"https://en.wikipedia.org/wiki/Bhartrihari","sourceTitle":"Book of Wise Sayings","sourceUrl":"https://www.gutenberg.org/cache/epub/21130/pg21130.txt","sourceSha256":"241fc6dd48bde0eaa24c2335184f566962f6a90e4b94a971b70d9600598a7fae"}',
  '{"definitionId":"visited-biscayne","slot":2,"id":"historic-quotation/q-b4a33b31ddac5d4aff140e504c25c9cb","text":"Earnestness is enthusiasm tempered by reason.","person":"Blaise Pascal","personWikipediaUrl":"https://en.wikipedia.org/wiki/Blaise_Pascal","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-black-canyon-gunnison","slot":1,"id":"historic-quotation/q-b58cff6d7dd799640bdf47d1d6133cdc","text":"A successful career has been full of blunders.","person":"Charles Buxton","personWikipediaUrl":"https://en.wikipedia.org/wiki/Charles_Buxton","sourceTitle":"Pearls of Thought","sourceUrl":"https://www.gutenberg.org/cache/epub/26604/pg26604.txt","sourceSha256":"bd029a4490008a4ee6ad5738df5ba723c2ba850092f9e9042b32e0fe5540a2b6"}',
  '{"definitionId":"visited-black-canyon-gunnison","slot":2,"id":"historic-quotation/q-248817c8dcbd4e760cf0517956b0d6ab","text":"Contemporaries appreciate the man rather than the merit; but posterity will regard the merit rather than the man.","person":"Charles Caleb Colton","personWikipediaUrl":"https://en.wikipedia.org/wiki/Charles_Caleb_Colton","sourceTitle":"Pearls of Thought","sourceUrl":"https://www.gutenberg.org/cache/epub/26604/pg26604.txt","sourceSha256":"bd029a4490008a4ee6ad5738df5ba723c2ba850092f9e9042b32e0fe5540a2b6"}',
  '{"definitionId":"visited-bryce-canyon","slot":1,"id":"historic-quotation/q-31ad981da9916515ded40d94330c7da2","text":"A loving heart is the truest wisdom.","person":"Charles Dickens","personWikipediaUrl":"https://en.wikipedia.org/wiki/Charles_Dickens","sourceTitle":"Pearls of Thought","sourceUrl":"https://www.gutenberg.org/cache/epub/26604/pg26604.txt","sourceSha256":"bd029a4490008a4ee6ad5738df5ba723c2ba850092f9e9042b32e0fe5540a2b6"}',
  '{"definitionId":"visited-bryce-canyon","slot":2,"id":"historic-quotation/q-6288a9dfb5dcb0976cb82f2bb2a9b35a","text":"Care of riches should have the last place in our thoughts","person":"Charles Dudley Warner","personWikipediaUrl":"https://en.wikipedia.org/wiki/Charles_Dudley_Warner","sourceTitle":"Quotations from the Project Gutenberg Editions of the Works of Charles Dudley Warner","sourceUrl":"https://www.gutenberg.org/cache/epub/3471/pg3471.txt","sourceSha256":"29ea89b07f35cc0adf1d31a507a5bff5c564243cdc62d45fb26baf54a807d3fe"}',
  '{"definitionId":"visited-canyonlands","slot":1,"id":"historic-quotation/q-a6ddee924f1ad89a6c2fefe48e538438","text":"Silence, when nothing need be said, is the eloquence of discretion.","person":"Christian Nestell Bovee","personWikipediaUrl":"https://en.wikipedia.org/wiki/Christian_Nestell_Bovee","sourceTitle":"Many Thoughts of Many Minds","sourceUrl":"https://www.gutenberg.org/cache/epub/17112/pg17112.txt","sourceSha256":"54ff4ba19eb9dd7b367d8f9893dd07fad81e5ce8b71bd5db5b38676c68221c21"}',
  '{"definitionId":"visited-canyonlands","slot":2,"id":"historic-quotation/q-20d26d9e4e7eea3eb0a0b659bfa6736f","text":"Erst the cold days show how fir and cypress are last to fade.","person":"Confucius","personWikipediaUrl":"https://en.wikipedia.org/wiki/Confucius","sourceTitle":"The Sayings of Confucius","sourceUrl":"https://www.gutenberg.org/cache/epub/24055/pg24055.txt","sourceSha256":"dfa209bdf6f902937fda12d487635d95f72285c0a433e3cf8e7bfe2e8e9c8be8"}',
  '{"definitionId":"visited-capitol-reef","slot":1,"id":"historic-quotation/q-80d705b594b0cae3a1e2933412977108","text":"Worldly fame is but a breath of wind, that blows now this way, now that, and changes name as it changes sides.","person":"Dante Alighieri","personWikipediaUrl":"https://en.wikipedia.org/wiki/Dante_Alighieri","sourceTitle":"Book of Wise Sayings","sourceUrl":"https://www.gutenberg.org/cache/epub/21130/pg21130.txt","sourceSha256":"241fc6dd48bde0eaa24c2335184f566962f6a90e4b94a971b70d9600598a7fae"}',
  '{"definitionId":"visited-capitol-reef","slot":2,"id":"historic-quotation/q-5d5f2f799aa01f6538c08037aad719a3","text":"The more men refine upon pleasure, the less will they indulge in excesses of any kind.","person":"David Hume","personWikipediaUrl":"https://en.wikipedia.org/wiki/David_Hume","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-carlsbad-caverns","slot":1,"id":"historic-quotation/q-0fd501a99006b3f71e20b6d6de38481f","text":"Our patience will achieve more than our force.","person":"Edmund Burke","personWikipediaUrl":"https://en.wikipedia.org/wiki/Edmund_Burke","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-carlsbad-caverns","slot":2,"id":"historic-quotation/q-1bcec235687ea5c732a4e7a5ce64a1d0","text":"The rust rots the steel which use preserves.","person":"Edward Bulwer-Lytton","personWikipediaUrl":"https://en.wikipedia.org/wiki/Edward_Bulwer-Lytton","sourceTitle":"Many Thoughts of Many Minds","sourceUrl":"https://www.gutenberg.org/cache/epub/17112/pg17112.txt","sourceSha256":"54ff4ba19eb9dd7b367d8f9893dd07fad81e5ce8b71bd5db5b38676c68221c21"}',
  '{"definitionId":"visited-channel-islands","slot":1,"id":"historic-quotation/q-be32d6c867362d49947fe02892dfc305","text":"Conversation enriches the understanding, but solitude is the school of genius.","person":"Edward Gibbon","personWikipediaUrl":"https://en.wikipedia.org/wiki/Edward_Gibbon","sourceTitle":"Pearls of Thought","sourceUrl":"https://www.gutenberg.org/cache/epub/26604/pg26604.txt","sourceSha256":"bd029a4490008a4ee6ad5738df5ba723c2ba850092f9e9042b32e0fe5540a2b6"}',
  '{"definitionId":"visited-channel-islands","slot":2,"id":"historic-quotation/q-bf659298dde4dbb5a096c17746525d16","text":"Learning makes a man fit company for himself.","person":"Edward Young","personWikipediaUrl":"https://en.wikipedia.org/wiki/Edward_Young","sourceTitle":"Many Thoughts of Many Minds","sourceUrl":"https://www.gutenberg.org/cache/epub/17112/pg17112.txt","sourceSha256":"54ff4ba19eb9dd7b367d8f9893dd07fad81e5ce8b71bd5db5b38676c68221c21"}',
  '{"definitionId":"visited-congaree","slot":1,"id":"historic-quotation/q-2375f8ccac96023b631449bca2d2e1d1","text":"Goodness consists not in the outward things we do, but in the inward thing we are.","person":"Edwin Hubbell Chapin","personWikipediaUrl":"https://en.wikipedia.org/wiki/Edwin_Hubbell_Chapin","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-congaree","slot":2,"id":"historic-quotation/q-ab067ffb2b23a713292f4a0b37242f87","text":"Even in social life, it is persistency which attracts confidence, more than talents and accomplishments.","person":"Edwin Percy Whipple","personWikipediaUrl":"https://en.wikipedia.org/wiki/Edwin_Percy_Whipple","sourceTitle":"Many Thoughts of Many Minds","sourceUrl":"https://www.gutenberg.org/cache/epub/17112/pg17112.txt","sourceSha256":"54ff4ba19eb9dd7b367d8f9893dd07fad81e5ce8b71bd5db5b38676c68221c21"}',
  '{"definitionId":"visited-crater-lake","slot":1,"id":"historic-quotation/q-731eedd405a3c328dd8c6ca91a07159f","text":"A ship should not ride on a single anchor, nor life on a single hope.","person":"Epictetus","personWikipediaUrl":"https://en.wikipedia.org/wiki/Epictetus","sourceTitle":"The Golden Sayings of Epictetus","sourceUrl":"https://www.gutenberg.org/cache/epub/871/pg871.txt","sourceSha256":"354cd7054206a1c9f441f588efa77451c9aa47a043eb144127818f13f41d7786"}',
  '{"definitionId":"visited-crater-lake","slot":2,"id":"historic-quotation/q-a4d74b4e5534e0ca496046c5cb532e63","text":"Adorn thy mind with knowledge, for knowledge maketh thy worth.","person":"Ferdowsi","personWikipediaUrl":"https://en.wikipedia.org/wiki/Ferdowsi","sourceTitle":"Book of Wise Sayings","sourceUrl":"https://www.gutenberg.org/cache/epub/21130/pg21130.txt","sourceSha256":"241fc6dd48bde0eaa24c2335184f566962f6a90e4b94a971b70d9600598a7fae"}',
  '{"definitionId":"visited-cuyahoga-valley","slot":1,"id":"historic-quotation/q-64a68a08452e5c3182fb116267ebbaab","text":"It is easy to lose important opportunities, and difficult to regain them; therefore when they present themselves it is the more necessary to make every effort to retain them.","person":"Francesco Guicciardini","personWikipediaUrl":"https://en.wikipedia.org/wiki/Francesco_Guicciardini","sourceTitle":"Book of Wise Sayings","sourceUrl":"https://www.gutenberg.org/cache/epub/21130/pg21130.txt","sourceSha256":"241fc6dd48bde0eaa24c2335184f566962f6a90e4b94a971b70d9600598a7fae"}',
  '{"definitionId":"visited-cuyahoga-valley","slot":2,"id":"historic-quotation/q-8c20fe142ab402fce3ad76bda9c36bb3","text":"Discretion in speech is more than eloquence.","person":"Francis Bacon","personWikipediaUrl":"https://en.wikipedia.org/wiki/Francis_Bacon","sourceTitle":"Many Thoughts of Many Minds","sourceUrl":"https://www.gutenberg.org/cache/epub/17112/pg17112.txt","sourceSha256":"54ff4ba19eb9dd7b367d8f9893dd07fad81e5ce8b71bd5db5b38676c68221c21"}',
  '{"definitionId":"visited-death-valley","slot":1,"id":"historic-quotation/q-976bc693fea68bd11a806711f4c93ed2","text":"Day follows the murkiest night; and when the time comes, the latest fruits also ripen.","person":"Friedrich Schiller","personWikipediaUrl":"https://en.wikipedia.org/wiki/Friedrich_Schiller","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-death-valley","slot":2,"id":"historic-quotation/q-d8dfc3fac22362a0e93602929c110858","text":"No story is the same to us after a lapse of time; or rather we who read it are no longer the same interpreters.","person":"George Eliot","personWikipediaUrl":"https://en.wikipedia.org/wiki/George_Eliot","sourceTitle":"Pearls of Thought","sourceUrl":"https://www.gutenberg.org/cache/epub/26604/pg26604.txt","sourceSha256":"bd029a4490008a4ee6ad5738df5ba723c2ba850092f9e9042b32e0fe5540a2b6"}',
  '{"definitionId":"visited-denali","slot":1,"id":"historic-quotation/q-78e56a513b883dc732b0d99b0ba5d023","text":"Usefulness comes by labour, wit by ease.","person":"George Herbert","personWikipediaUrl":"https://en.wikipedia.org/wiki/George_Herbert","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-denali","slot":2,"id":"historic-quotation/q-95e5851de1d6a958f6dde61aa0906377","text":"When we destroy an old prejudice, we have need of a new virtue.","person":"Germaine de Staël","personWikipediaUrl":"https://en.wikipedia.org/wiki/Germaine_de_Sta%C3%ABl","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-dry-tortugas","slot":1,"id":"historic-quotation/q-120bfc60870d9de69de62c48338a6a0b","text":"Art does not imitate, but interpret.","person":"Giuseppe Mazzini","personWikipediaUrl":"https://en.wikipedia.org/wiki/Giuseppe_Mazzini","sourceTitle":"Pearls of Thought","sourceUrl":"https://www.gutenberg.org/cache/epub/26604/pg26604.txt","sourceSha256":"bd029a4490008a4ee6ad5738df5ba723c2ba850092f9e9042b32e0fe5540a2b6"}',
  '{"definitionId":"visited-dry-tortugas","slot":2,"id":"historic-quotation/q-6aec48306821b551a4ac1e52f5eeb35e","text":"Every age has its problem, by solving which, humanity is helped forward.","person":"Heinrich Heine","personWikipediaUrl":"https://en.wikipedia.org/wiki/Heinrich_Heine","sourceTitle":"Pearls of Thought","sourceUrl":"https://www.gutenberg.org/cache/epub/26604/pg26604.txt","sourceSha256":"bd029a4490008a4ee6ad5738df5ba723c2ba850092f9e9042b32e0fe5540a2b6"}',
  '{"definitionId":"visited-everglades","slot":1,"id":"historic-quotation/q-b01be8c054f0e0484058549ed12d5eec","text":"So long as a man is capable of self-renewal he is a living being.","person":"Henri-Frédéric Amiel","personWikipediaUrl":"https://en.wikipedia.org/wiki/Henri-Fr%C3%A9d%C3%A9ric_Amiel","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-everglades","slot":2,"id":"historic-quotation/q-e96c9845454906f21b91b53478e5023a","text":"Nothing makes the earth seem so spacious as to have friends at a distance; they make the latitudes and longitudes.","person":"Henry David Thoreau","personWikipediaUrl":"https://en.wikipedia.org/wiki/Henry_David_Thoreau","sourceTitle":"Pearls of Thought","sourceUrl":"https://www.gutenberg.org/cache/epub/26604/pg26604.txt","sourceSha256":"bd029a4490008a4ee6ad5738df5ba723c2ba850092f9e9042b32e0fe5540a2b6"}',
  '{"definitionId":"visited-gates-of-the-arctic","slot":1,"id":"historic-quotation/q-87e5c0809b5007764c91c171da1cffc5","text":"Dignity is the salt of art.","person":"Henry Fuseli","personWikipediaUrl":"https://en.wikipedia.org/wiki/Henry_Fuseli","sourceTitle":"The Life and Writings of Henry Fuseli, Volume 3: Aphorisms, Chiefly Relative to the Fine Arts","sourceUrl":"https://www.gutenberg.org/cache/epub/40474/pg40474.txt","sourceSha256":"0c3311df36f322386e02996cf5a17ecaf97f021d721ddc286ea66f7ecfa03fea"}',
  '{"definitionId":"visited-gates-of-the-arctic","slot":2,"id":"historic-quotation/q-030c1eb5f4a1f6580f61b5a38ef56728","text":"There is a strength of quiet endurance as significant of courage as the most daring feats of prowess.","person":"Henry Theodore Tuckerman","personWikipediaUrl":"https://en.wikipedia.org/wiki/Henry_Theodore_Tuckerman","sourceTitle":"Pearls of Thought","sourceUrl":"https://www.gutenberg.org/cache/epub/26604/pg26604.txt","sourceSha256":"bd029a4490008a4ee6ad5738df5ba723c2ba850092f9e9042b32e0fe5540a2b6"}',
  '{"definitionId":"visited-gateway-arch","slot":1,"id":"historic-quotation/q-92d3d334956874001b49d3c6e9823c06","text":"The only progress which is really effective depends, not upon the bounty of Nature, but upon the energy of man.","person":"Henry Thomas Buckle","personWikipediaUrl":"https://en.wikipedia.org/wiki/Henry_Thomas_Buckle","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-gateway-arch","slot":2,"id":"historic-quotation/q-c8a5edeb34600c7478a379c75adb7da9","text":"We judge ourselves by what we feel capable of doing, while others judge us by what we have already done.","person":"Henry Wadsworth Longfellow","personWikipediaUrl":"https://en.wikipedia.org/wiki/Henry_Wadsworth_Longfellow","sourceTitle":"Many Thoughts of Many Minds","sourceUrl":"https://www.gutenberg.org/cache/epub/17112/pg17112.txt","sourceSha256":"54ff4ba19eb9dd7b367d8f9893dd07fad81e5ce8b71bd5db5b38676c68221c21"}',
  '{"definitionId":"visited-glacier-bay","slot":1,"id":"historic-quotation/q-25590d8002285897622b8078daa9af01","text":"Genius unexerted is no more genius than a bushel of acorns is a forest of oaks.","person":"Henry Ward Beecher","personWikipediaUrl":"https://en.wikipedia.org/wiki/Henry_Ward_Beecher","sourceTitle":"Many Thoughts of Many Minds","sourceUrl":"https://www.gutenberg.org/cache/epub/17112/pg17112.txt","sourceSha256":"54ff4ba19eb9dd7b367d8f9893dd07fad81e5ce8b71bd5db5b38676c68221c21"}',
  '{"definitionId":"visited-glacier-bay","slot":2,"id":"historic-quotation/q-2010da779679c09143fd4f9273cc17e7","text":"The more one judges, the less one loves.","person":"Honoré de Balzac","personWikipediaUrl":"https://en.wikipedia.org/wiki/Honor%C3%A9_de_Balzac","sourceTitle":"Pearls of Thought","sourceUrl":"https://www.gutenberg.org/cache/epub/26604/pg26604.txt","sourceSha256":"bd029a4490008a4ee6ad5738df5ba723c2ba850092f9e9042b32e0fe5540a2b6"}',
  '{"definitionId":"visited-glacier","slot":1,"id":"historic-quotation/q-cc1d680ac177e43cd665646354660198","text":"Genius may conceive, but patient labor must consummate.","person":"Horace Mann","personWikipediaUrl":"https://en.wikipedia.org/wiki/Horace_Mann","sourceTitle":"Many Thoughts of Many Minds","sourceUrl":"https://www.gutenberg.org/cache/epub/17112/pg17112.txt","sourceSha256":"54ff4ba19eb9dd7b367d8f9893dd07fad81e5ce8b71bd5db5b38676c68221c21"}',
  '{"definitionId":"visited-glacier","slot":2,"id":"historic-quotation/q-4ba73e4bb2467bdfe2d85c415091d608","text":"Unless we find repose within ourselves, it is vain to seek it elsewhere.","person":"Hosea Ballou","personWikipediaUrl":"https://en.wikipedia.org/wiki/Hosea_Ballou","sourceTitle":"Many Thoughts of Many Minds","sourceUrl":"https://www.gutenberg.org/cache/epub/17112/pg17112.txt","sourceSha256":"54ff4ba19eb9dd7b367d8f9893dd07fad81e5ce8b71bd5db5b38676c68221c21"}',
  '{"definitionId":"visited-grand-canyon","slot":1,"id":"historic-quotation/q-dc729e18ef05b9accc900ce91e57a113","text":"The praise that comes of love does not make us vain, but humble rather.","person":"J. M. Barrie","personWikipediaUrl":"https://en.wikipedia.org/wiki/J._M._Barrie","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-grand-canyon","slot":2,"id":"historic-quotation/q-b2123f80b3123feea2e12ed9ff8dae90","text":"Solitude is as needful to the imagination as society is wholesome for the character.","person":"James Russell Lowell","personWikipediaUrl":"https://en.wikipedia.org/wiki/James_Russell_Lowell","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-grand-teton","slot":1,"id":"historic-quotation/q-299c3676676a1b0061c3089b0426ad17","text":"\'Tis easier for the generous to forgive than for offense to ask it.","person":"James Thomson","personWikipediaUrl":"https://en.wikipedia.org/wiki/James_Thomson_(poet,_born_1700)","sourceTitle":"Pearls of Thought","sourceUrl":"https://www.gutenberg.org/cache/epub/26604/pg26604.txt","sourceSha256":"bd029a4490008a4ee6ad5738df5ba723c2ba850092f9e9042b32e0fe5540a2b6"}',
  '{"definitionId":"visited-grand-teton","slot":2,"id":"historic-quotation/q-74cd60113e442b47328edd01b31ead89","text":"Liberality consists less in giving much than in giving at the right moment.","person":"Jean de La Bruyère","personWikipediaUrl":"https://en.wikipedia.org/wiki/Jean_de_La_Bruy%C3%A8re","sourceTitle":"Book of Wise Sayings","sourceUrl":"https://www.gutenberg.org/cache/epub/21130/pg21130.txt","sourceSha256":"241fc6dd48bde0eaa24c2335184f566962f6a90e4b94a971b70d9600598a7fae"}',
  '{"definitionId":"visited-great-basin","slot":1,"id":"historic-quotation/q-6c5bffd58d620c91b219b22a89561925","text":"All loving emotions, like plants, shoot up most rapidly in the tempestuous atmosphere of life.","person":"Jean Paul","personWikipediaUrl":"https://en.wikipedia.org/wiki/Jean_Paul","sourceTitle":"Pearls of Thought","sourceUrl":"https://www.gutenberg.org/cache/epub/26604/pg26604.txt","sourceSha256":"bd029a4490008a4ee6ad5738df5ba723c2ba850092f9e9042b32e0fe5540a2b6"}',
  '{"definitionId":"visited-great-basin","slot":2,"id":"historic-quotation/q-81900a7ee35ee25fde44733c225757cf","text":"Patience is bitter, but its fruit is sweet.","person":"Jean-Jacques Rousseau","personWikipediaUrl":"https://en.wikipedia.org/wiki/Jean-Jacques_Rousseau","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-great-sand-dunes","slot":1,"id":"historic-quotation/q-075f713a40add9f524bee84447e60464","text":"Perpetual pushing and assurance put a difficulty out of countenance, and make a seeming impossibility give way.","person":"Jeremy Collier","personWikipediaUrl":"https://en.wikipedia.org/wiki/Jeremy_Collier","sourceTitle":"Pearls of Thought","sourceUrl":"https://www.gutenberg.org/cache/epub/26604/pg26604.txt","sourceSha256":"bd029a4490008a4ee6ad5738df5ba723c2ba850092f9e9042b32e0fe5540a2b6"}',
  '{"definitionId":"visited-great-sand-dunes","slot":2,"id":"historic-quotation/q-566e52eb30a70e428722487ab4f57d12","text":"There is no mortal truly wise and restless at once; wisdom is the repose of minds.","person":"Johann Kaspar Lavater","personWikipediaUrl":"https://en.wikipedia.org/wiki/Johann_Kaspar_Lavater","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-great-smoky-mountains","slot":1,"id":"historic-quotation/q-aaaee00de437b09e0a8e87abbd8ad332","text":"A day of fortune is like a harvest-day, we must be busy when the corn is ripe.","person":"Johann Wolfgang von Goethe","personWikipediaUrl":"https://en.wikipedia.org/wiki/Johann_Wolfgang_von_Goethe","sourceTitle":"Book of Wise Sayings","sourceUrl":"https://www.gutenberg.org/cache/epub/21130/pg21130.txt","sourceSha256":"241fc6dd48bde0eaa24c2335184f566962f6a90e4b94a971b70d9600598a7fae"}',
  '{"definitionId":"visited-great-smoky-mountains","slot":2,"id":"historic-quotation/q-f071f8bee114d73453ee12d0867aafc6","text":"Wisdom will out; it is the one thing in this world that cannot be suppressed or annulled.","person":"John Burroughs","personWikipediaUrl":"https://en.wikipedia.org/wiki/John_Burroughs","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-guadalupe-mountains","slot":1,"id":"historic-quotation/q-d36ad4147e2c6fcb95f682400b99d7ca","text":"Courage from hearts, and not from numbers, grows.","person":"John Dryden","personWikipediaUrl":"https://en.wikipedia.org/wiki/John_Dryden","sourceTitle":"Pearls of Thought","sourceUrl":"https://www.gutenberg.org/cache/epub/26604/pg26604.txt","sourceSha256":"bd029a4490008a4ee6ad5738df5ba723c2ba850092f9e9042b32e0fe5540a2b6"}',
  '{"definitionId":"visited-guadalupe-mountains","slot":2,"id":"historic-quotation/q-4fca1cf7d7ac659721eb76b41c6c1a4f","text":"Beneath the Winter\'s snow lie germs of summer flowers.","person":"John Greenleaf Whittier","personWikipediaUrl":"https://en.wikipedia.org/wiki/John_Greenleaf_Whittier","sourceTitle":"Pearls of Thought","sourceUrl":"https://www.gutenberg.org/cache/epub/26604/pg26604.txt","sourceSha256":"bd029a4490008a4ee6ad5738df5ba723c2ba850092f9e9042b32e0fe5540a2b6"}',
  '{"definitionId":"visited-haleakala","slot":1,"id":"historic-quotation/q-46af738ced7fac36f44a1a73d4c11119","text":"A thing of beauty is a joy forever; Its loveliness increases; it will never Pass into nothingness.","person":"John Keats","personWikipediaUrl":"https://en.wikipedia.org/wiki/John_Keats","sourceTitle":"Familiar Quotations","sourceUrl":"https://www.gutenberg.org/cache/epub/27889/pg27889.txt","sourceSha256":"28da04fea3f40e0810b63102e30010479728230af8436f3f83ebdf8b32b9f1fb"}',
  '{"definitionId":"visited-haleakala","slot":2,"id":"historic-quotation/q-90755cb653cb07d94927c4776ffeef0e","text":"Reading furnishes us only with the materials of knowledge; it is thinking makes what we read ours.","person":"John Locke","personWikipediaUrl":"https://en.wikipedia.org/wiki/John_Locke","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-hawaii-volcanoes","slot":1,"id":"historic-quotation/q-4ba8ba722ae274723835ac3029a42066","text":"Good, the more communicated, more abundant grows.","person":"John Milton","personWikipediaUrl":"https://en.wikipedia.org/wiki/John_Milton","sourceTitle":"Pearls of Thought","sourceUrl":"https://www.gutenberg.org/cache/epub/26604/pg26604.txt","sourceSha256":"bd029a4490008a4ee6ad5738df5ba723c2ba850092f9e9042b32e0fe5540a2b6"}',
  '{"definitionId":"visited-hawaii-volcanoes","slot":2,"id":"historic-quotation/q-24cff664483ca006c1310d5ca66c3c6c","text":"The habit and power of reading with reflection, comprehension, and memory all alert and awake, does not come at once to the natural man any more than many other sovereign virtues.","person":"John Morley","personWikipediaUrl":"https://en.wikipedia.org/wiki/John_Morley","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-hot-springs","slot":1,"id":"historic-quotation/q-a33d3de21a0e65f2770ee995ab842329","text":"It takes a great deal of living to get a little deal of learning.","person":"John Ruskin","personWikipediaUrl":"https://en.wikipedia.org/wiki/John_Ruskin","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-hot-springs","slot":2,"id":"historic-quotation/q-a93599ddc13ebafcc305107b7adcf5f4","text":"The only freedom which deserves the name is that of pursuing our own good in our own way, so long as we do not attempt to deprive others of this, or impede their efforts to obtain it.","person":"John Stuart Mill","personWikipediaUrl":"https://en.wikipedia.org/wiki/John_Stuart_Mill","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-indiana-dunes","slot":1,"id":"historic-quotation/q-2f741c9caa79c651a8e69b4b86e92ef5","text":"Truth is the shortest and nearest way to our end, carrying us thither in a straight line.","person":"John Tillotson","personWikipediaUrl":"https://en.wikipedia.org/wiki/John_Tillotson","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-indiana-dunes","slot":2,"id":"historic-quotation/q-4d2c3cc2c6ab10084f026ce94b0a4bbf","text":"There is no real life but cheerful life.","person":"Joseph Addison","personWikipediaUrl":"https://en.wikipedia.org/wiki/Joseph_Addison","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-isle-royale","slot":1,"id":"historic-quotation/q-3a399cbefceeb7aca06016d246e599c1","text":"Politeness is to goodness what words are to thoughts.","person":"Joseph Joubert","personWikipediaUrl":"https://en.wikipedia.org/wiki/Joseph_Joubert","sourceTitle":"Many Thoughts of Many Minds","sourceUrl":"https://www.gutenberg.org/cache/epub/17112/pg17112.txt","sourceSha256":"54ff4ba19eb9dd7b367d8f9893dd07fad81e5ce8b71bd5db5b38676c68221c21"}',
  '{"definitionId":"visited-isle-royale","slot":2,"id":"historic-quotation/q-8e151f4ddd59b29516eefb2e018f8567","text":"Words are often seen hunting for an idea, but ideas are never seen hunting for words.","person":"Josh Billings","personWikipediaUrl":"https://en.wikipedia.org/wiki/Josh_Billings","sourceTitle":"Many Thoughts of Many Minds","sourceUrl":"https://www.gutenberg.org/cache/epub/17112/pg17112.txt","sourceSha256":"54ff4ba19eb9dd7b367d8f9893dd07fad81e5ce8b71bd5db5b38676c68221c21"}',
  '{"definitionId":"visited-joshua-tree","slot":1,"id":"historic-quotation/q-82cba1af95510002fa1e50c3b2524b6d","text":"Work was made for man, and not man for work.","person":"Josiah Gilbert Holland","personWikipediaUrl":"https://en.wikipedia.org/wiki/Josiah_Gilbert_Holland","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-joshua-tree","slot":2,"id":"historic-quotation/q-b4a5806a60873b36b2af89937a128bc4","text":"In solitude the mind gains strength and learns to lean upon itself.","person":"Laurence Sterne","personWikipediaUrl":"https://en.wikipedia.org/wiki/Laurence_Sterne","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-katmai","slot":1,"id":"historic-quotation/q-60ff660e5389198cb588099c77b7b98d","text":"All our knowledge is the offspring of our perceptions.","person":"Leonardo da Vinci","personWikipediaUrl":"https://en.wikipedia.org/wiki/Leonardo_da_Vinci","sourceTitle":"Thoughts on Art and Life","sourceUrl":"https://www.gutenberg.org/cache/epub/29904/pg29904.txt","sourceSha256":"323f8893f03432a5b17a3f83ef698d1369a93dce41bdb16176653e85ba1a2c66"}',
  '{"definitionId":"visited-katmai","slot":2,"id":"historic-quotation/q-e443322ce68efd17d6005d1e627fbd97","text":"Toil and pleasure, in their natures opposite, are yet linked together in a kind of necessary connection.","person":"Livy","personWikipediaUrl":"https://en.wikipedia.org/wiki/Livy","sourceTitle":"Book of Wise Sayings: Selected Largely from Eastern Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/21130/pg21130.txt","sourceSha256":"241fc6dd48bde0eaa24c2335184f566962f6a90e4b94a971b70d9600598a7fae"}',
  '{"definitionId":"visited-kenai-fjords","slot":1,"id":"historic-quotation/q-ab247f4307d6cf900d4852eec82d20a1","text":"All who joy would win Must share it, happiness was born a twin.","person":"Lord Byron","personWikipediaUrl":"https://en.wikipedia.org/wiki/Lord_Byron","sourceTitle":"Familiar Quotations","sourceUrl":"https://www.gutenberg.org/cache/epub/27889/pg27889.txt","sourceSha256":"28da04fea3f40e0810b63102e30010479728230af8436f3f83ebdf8b32b9f1fb"}',
  '{"definitionId":"visited-kenai-fjords","slot":2,"id":"historic-quotation/q-1c58ac5e4a1e47babfb03a0594d4d25a","text":"Great thoughts come from the heart.","person":"Luc de Clapiers, marquis de Vauvenargues","personWikipediaUrl":"https://en.wikipedia.org/wiki/Luc_de_Clapiers,_marquis_de_Vauvenargues","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-kings-canyon","slot":1,"id":"historic-quotation/q-96c6062b621eda70283b0ab9bac96321","text":"What profits not the swarm profits not the bee.","person":"Marcus Aurelius","personWikipediaUrl":"https://en.wikipedia.org/wiki/Marcus_Aurelius","sourceTitle":"The Meditations of the Emperor Marcus Aurelius Antoninus","sourceUrl":"https://www.gutenberg.org/cache/epub/55317/pg55317.txt","sourceSha256":"0ad812a88fee716849776c0dcbd2dd7c8246d79bfee9781b2758917760b173d5"}',
  '{"definitionId":"visited-kings-canyon","slot":2,"id":"historic-quotation/q-d7c67ffad1788b4efa5bf53fe9a8c2c7","text":"As storm following storm, and wave succeeding wave, give additional hardness to the shell that encloses the pearl, so do the storms and waves of life add force to the character of man.","person":"Marguerite Gardiner, Countess of Blessington","personWikipediaUrl":"https://en.wikipedia.org/wiki/Marguerite_Gardiner,_Countess_of_Blessington","sourceTitle":"Desultory Thoughts and Reflections","sourceUrl":"https://www.gutenberg.org/cache/epub/75737/pg75737.txt","sourceSha256":"9261723ed516a715c977bee43c07f00e79fd6448012f2555b9ee5de340ed031a"}',
  '{"definitionId":"visited-kobuk-valley","slot":1,"id":"historic-quotation/q-9f9e0e389f0500f18279510ca1d2273d","text":"One thought cannot awake without awakening others.","person":"Marie von Ebner-Eschenbach","personWikipediaUrl":"https://en.wikipedia.org/wiki/Marie_von_Ebner-Eschenbach","sourceTitle":"Many Thoughts of Many Minds","sourceUrl":"https://www.gutenberg.org/cache/epub/17112/pg17112.txt","sourceSha256":"54ff4ba19eb9dd7b367d8f9893dd07fad81e5ce8b71bd5db5b38676c68221c21"}',
  '{"definitionId":"visited-kobuk-valley","slot":2,"id":"historic-quotation/q-c7ddfbc46eada5e41a684036c3295fb2","text":"In the long analysis of the ages it is the truth that counts","person":"Mark Twain","personWikipediaUrl":"https://en.wikipedia.org/wiki/Mark_Twain","sourceTitle":"Quotations from the Project Gutenberg Editions of the Works of Mark Twain","sourceUrl":"https://www.gutenberg.org/cache/epub/3432/pg3432.txt","sourceSha256":"68d4bb42877e8999ccdf986bfb3c663d83486f0d7d47ef41fbb1e2554e048b8a"}',
  '{"definitionId":"visited-lake-clark","slot":1,"id":"historic-quotation/q-176a2672279b66b78ee0033cee3bf0c8","text":"A generous heart ought not to belie its own thoughts","person":"Michel de Montaigne","personWikipediaUrl":"https://en.wikipedia.org/wiki/Michel_de_Montaigne","sourceTitle":"Widger\'s Quotations from the Project Gutenberg Editions of the Works of Montaigne","sourceUrl":"https://www.gutenberg.org/cache/epub/3661/pg3661.txt","sourceSha256":"8967e5fa2bd702eae39585cc9e7a0e248ad041ba38b3a20fe31265b579b4e40e"}',
  '{"definitionId":"visited-lake-clark","slot":2,"id":"historic-quotation/q-7d0f15d6cfcbf65218a9dc70647ac4a1","text":"Good actions ennoble us, and we are the sons of our own deeds.","person":"Miguel de Cervantes","personWikipediaUrl":"https://en.wikipedia.org/wiki/Miguel_de_Cervantes","sourceTitle":"Pearls of Thought","sourceUrl":"https://www.gutenberg.org/cache/epub/26604/pg26604.txt","sourceSha256":"bd029a4490008a4ee6ad5738df5ba723c2ba850092f9e9042b32e0fe5540a2b6"}',
  '{"definitionId":"visited-lassen-volcanic","slot":1,"id":"historic-quotation/q-f1b4a6340d7a4cfcdb78bd0d4609ae8e","text":"The love of reading enables a man to exchange the wearisome hours of life, which come to every one, for hours of delight.","person":"Montesquieu","personWikipediaUrl":"https://en.wikipedia.org/wiki/Montesquieu","sourceTitle":"Pearls of Thought","sourceUrl":"https://www.gutenberg.org/cache/epub/26604/pg26604.txt","sourceSha256":"bd029a4490008a4ee6ad5738df5ba723c2ba850092f9e9042b32e0fe5540a2b6"}',
  '{"definitionId":"visited-lassen-volcanic","slot":2,"id":"historic-quotation/q-243ff1bb7a3b6d60bde11887c2c7eee3","text":"Generosity is the flower of justice.","person":"Nathaniel Hawthorne","personWikipediaUrl":"https://en.wikipedia.org/wiki/Nathaniel_Hawthorne","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-mammoth-cave","slot":1,"id":"historic-quotation/q-52b472a374fd09639d386c073ef22250","text":"We take our colors, chameleon-like, from each other.","person":"Nicolas Chamfort","personWikipediaUrl":"https://en.wikipedia.org/wiki/Nicolas_Chamfort","sourceTitle":"Pearls of Thought","sourceUrl":"https://www.gutenberg.org/cache/epub/26604/pg26604.txt","sourceSha256":"bd029a4490008a4ee6ad5738df5ba723c2ba850092f9e9042b32e0fe5540a2b6"}',
  '{"definitionId":"visited-mammoth-cave","slot":2,"id":"historic-quotation/q-1ad546f980074c5ff0b94138ac452e15","text":"In the hour of adversity be not without hope, for crystal rain falls from black clouds.","person":"Nizami Ganjavi","personWikipediaUrl":"https://en.wikipedia.org/wiki/Nizami_Ganjavi","sourceTitle":"Book of Wise Sayings","sourceUrl":"https://www.gutenberg.org/cache/epub/21130/pg21130.txt","sourceSha256":"241fc6dd48bde0eaa24c2335184f566962f6a90e4b94a971b70d9600598a7fae"}',
  '{"definitionId":"visited-mesa-verde","slot":1,"id":"historic-quotation/q-75524885ca8d8f2d82ff0d49625fad4b","text":"Nature is an Æolian harp, a musical instrument whose tones are the re-echo of higher strings within us.","person":"Novalis","personWikipediaUrl":"https://en.wikipedia.org/wiki/Novalis","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-mesa-verde","slot":2,"id":"historic-quotation/q-cafbabd2d612d5e615ab3fd73c613fe8","text":"The ingratitude of the world can never deprive us of the conscious happiness of having acted with humanity ourselves.","person":"Oliver Goldsmith","personWikipediaUrl":"https://en.wikipedia.org/wiki/Oliver_Goldsmith","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-mount-rainier","slot":1,"id":"historic-quotation/q-aec378d936034e9d996735635c4dad38","text":"Beliefs must be lived in for a good while","person":"Oliver Wendell Holmes Sr.","personWikipediaUrl":"https://en.wikipedia.org/wiki/Oliver_Wendell_Holmes_Sr.","sourceTitle":"Widger\'s Quotations from the Project Gutenberg Editions of the Works of Oliver W. Holmes, Sr.","sourceUrl":"https://www.gutenberg.org/cache/epub/3493/pg3493.txt","sourceSha256":"5555b810cf767c77ffddf10242048512a01bac723f1f624a791e422819e66feb"}',
  '{"definitionId":"visited-mount-rainier","slot":2,"id":"historic-quotation/q-46ff65a0e2f43d94f3a1c538b9020cdc","text":"An echo is often more beautiful than the voice it repeats.","person":"Oscar Wilde","personWikipediaUrl":"https://en.wikipedia.org/wiki/Oscar_Wilde","sourceTitle":"Miscellaneous Aphorisms","sourceUrl":"https://www.gutenberg.org/cache/epub/33979/pg33979.txt","sourceSha256":"b2f26f9cca110780f4fcfe08aa5159f31306e6fe66c27d474dfdc5e95e40dfbf"}',
  '{"definitionId":"visited-national-park-american-samoa","slot":1,"id":"historic-quotation/q-90fc0f0eb5799683da4ff9bd3976f613","text":"What is reason now was passion formerly.","person":"Ovid","personWikipediaUrl":"https://en.wikipedia.org/wiki/Ovid","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-national-park-american-samoa","slot":2,"id":"historic-quotation/q-2b0f35a72823994032da72628fdf805c","text":"Virtue dwells at the head of a river, to which we cannot get but by rowing against the stream.","person":"Owen Feltham","personWikipediaUrl":"https://en.wikipedia.org/wiki/Owen_Feltham","sourceTitle":"Pearls of Thought","sourceUrl":"https://www.gutenberg.org/cache/epub/26604/pg26604.txt","sourceSha256":"bd029a4490008a4ee6ad5738df5ba723c2ba850092f9e9042b32e0fe5540a2b6"}',
  '{"definitionId":"visited-new-river-gorge","slot":1,"id":"historic-quotation/q-760d51bad02c13ec014662f89f96544f","text":"Weigh not so much what men say, as what they prove: remembering that truth is simple and naked, and needs not invective to apparel her comeliness.","person":"Philip Sidney","personWikipediaUrl":"https://en.wikipedia.org/wiki/Philip_Sidney","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-new-river-gorge","slot":2,"id":"historic-quotation/q-cb7c722fb7c3f81b78347ffbc4214f2a","text":"An able man shows his spirit by gentle words and resolute actions.","person":"Philip Stanhope, 4th Earl of Chesterfield","personWikipediaUrl":"https://en.wikipedia.org/wiki/Philip_Stanhope,_4th_Earl_of_Chesterfield","sourceTitle":"Many Thoughts of Many Minds","sourceUrl":"https://www.gutenberg.org/cache/epub/17112/pg17112.txt","sourceSha256":"54ff4ba19eb9dd7b367d8f9893dd07fad81e5ce8b71bd5db5b38676c68221c21"}',
  '{"definitionId":"visited-north-cascades","slot":1,"id":"historic-quotation/q-2ea8452b811f32eb4a7731dba3742c1c","text":"Let him take heart who does advance, even in the smallest degree.","person":"Plato","personWikipediaUrl":"https://en.wikipedia.org/wiki/Plato","sourceTitle":"Book of Wise Sayings","sourceUrl":"https://www.gutenberg.org/cache/epub/21130/pg21130.txt","sourceSha256":"241fc6dd48bde0eaa24c2335184f566962f6a90e4b94a971b70d9600598a7fae"}',
  '{"definitionId":"visited-north-cascades","slot":2,"id":"historic-quotation/q-7b3bb4e4433b2f33272a363b14c39546","text":"True greatness is sovereign wisdom. We are never deceived by our virtues.","person":"Alphonse de Lamartine","personWikipediaUrl":"https://en.wikipedia.org/wiki/Alphonse_de_Lamartine","sourceTitle":"Pearls of Thought","sourceUrl":"https://www.gutenberg.org/cache/epub/26604/pg26604.txt","sourceSha256":"bd029a4490008a4ee6ad5738df5ba723c2ba850092f9e9042b32e0fe5540a2b6"}',
  '{"definitionId":"visited-olympic","slot":1,"id":"historic-quotation/q-5c039accfdd9190e548ff1a9c788e365","text":"A gift in season is a double favor to the needy.","person":"Publilius Syrus","personWikipediaUrl":"https://en.wikipedia.org/wiki/Publilius_Syrus","sourceTitle":"The Moral Sayings of Publius Syrus, a Roman Slave","sourceUrl":"https://en.wikisource.org/wiki/The_Moral_Sayings_of_Publius_Syrus%2C_A_Roman_Slave?printable=yes","sourceSha256":"155e6832121547772bf11fa24feb36883a3b392cdb09101183929fe15cc43973"}',
  '{"definitionId":"visited-olympic","slot":2,"id":"historic-quotation/q-6f57e3072d3b71bd98f8fe55ee9d49bd","text":"If you shut your door to all errors truth will be shut out.","person":"Rabindranath Tagore","personWikipediaUrl":"https://en.wikipedia.org/wiki/Rabindranath_Tagore","sourceTitle":"Stray Birds","sourceUrl":"https://www.gutenberg.org/cache/epub/6524/pg6524.txt","sourceSha256":"b8ad6f2827cb2b8496e386e583c93d6a4ce2525a24887d03ca361f5253eb5f9f"}',
  '{"definitionId":"visited-petrified-forest","slot":1,"id":"historic-quotation/q-16b8e7542278fa9d903a27e5bc7d2104","text":"A great man is always willing to be little.","person":"Ralph Waldo Emerson","personWikipediaUrl":"https://en.wikipedia.org/wiki/Ralph_Waldo_Emerson","sourceTitle":"The Wisdom of Ralph Waldo Emerson: Being Extracts from His Prose and Verse","sourceUrl":"https://archive.org/download/wisdomralphwald00parkgoog/wisdomralphwald00parkgoog_djvu.txt","sourceSha256":"325b25b72d66c0d6cff42367ad492b26cab54375e8eaaa6e2e51830e0f639a00"}',
  '{"definitionId":"visited-petrified-forest","slot":2,"id":"historic-quotation/q-cf76008c3b4b27a765fadc1e8bb80cb3","text":"A life spent worthily should be measured by a nobler line,--by deeds, not years.","person":"Richard Brinsley Sheridan","personWikipediaUrl":"https://en.wikipedia.org/wiki/Richard_Brinsley_Sheridan","sourceTitle":"Pearls of Thought","sourceUrl":"https://www.gutenberg.org/cache/epub/26604/pg26604.txt","sourceSha256":"bd029a4490008a4ee6ad5738df5ba723c2ba850092f9e9042b32e0fe5540a2b6"}',
  '{"definitionId":"visited-pinnacles","slot":1,"id":"historic-quotation/q-6902c66ff350c9eb704dec957872f992","text":"What \'s done we partly may compute, But know not what \'s resisted.","person":"Robert Burns","personWikipediaUrl":"https://en.wikipedia.org/wiki/Robert_Burns","sourceTitle":"Familiar Quotations","sourceUrl":"https://www.gutenberg.org/cache/epub/27889/pg27889.txt","sourceSha256":"28da04fea3f40e0810b63102e30010479728230af8436f3f83ebdf8b32b9f1fb"}',
  '{"definitionId":"visited-pinnacles","slot":2,"id":"historic-quotation/q-1edacb06738eba9b0879f7afdaeb9bf6","text":"True nobility is derived from virtue, not birth.","person":"Robert Burton","personWikipediaUrl":"https://en.wikipedia.org/wiki/Robert_Burton_(scholar)","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-redwood","slot":1,"id":"historic-quotation/q-b7e3e82d1413d7b810441056ba37b510","text":"It is better to be well deserving without praise than to live by the air of undeserved commendation.","person":"Robert Chamberlain","personWikipediaUrl":"https://en.wikipedia.org/wiki/Robert_Chamberlain_(poet)","sourceTitle":"Book of Wise Sayings","sourceUrl":"https://www.gutenberg.org/cache/epub/21130/pg21130.txt","sourceSha256":"241fc6dd48bde0eaa24c2335184f566962f6a90e4b94a971b70d9600598a7fae"}',
  '{"definitionId":"visited-redwood","slot":2,"id":"historic-quotation/q-ce82c8d557159556ada55a48b6521906","text":"Society is built upon trust, and trust upon confidence of one another\'s integrity.","person":"Robert South","personWikipediaUrl":"https://en.wikipedia.org/wiki/Robert_South","sourceTitle":"Pearls of Thought","sourceUrl":"https://www.gutenberg.org/cache/epub/26604/pg26604.txt","sourceSha256":"bd029a4490008a4ee6ad5738df5ba723c2ba850092f9e9042b32e0fe5540a2b6"}',
  '{"definitionId":"visited-rocky-mountain","slot":1,"id":"historic-quotation/q-4e8c874aa3ce65c63e3e432197c52f5a","text":"Pleasure is very seldom found where it is sought. Our brightest blazes of gladness are commonly kindled by unexpected sparks.","person":"Samuel Johnson","personWikipediaUrl":"https://en.wikipedia.org/wiki/Samuel_Johnson","sourceTitle":"Pearls of Thought","sourceUrl":"https://www.gutenberg.org/cache/epub/26604/pg26604.txt","sourceSha256":"bd029a4490008a4ee6ad5738df5ba723c2ba850092f9e9042b32e0fe5540a2b6"}',
  '{"definitionId":"visited-rocky-mountain","slot":2,"id":"historic-quotation/q-18b3bfb7027035cd1c41dddb2ea1d77a","text":"Cheerfulness is also an excellent wearing quality. It has been called the bright weather of the heart.","person":"Samuel Smiles","personWikipediaUrl":"https://en.wikipedia.org/wiki/Samuel_Smiles","sourceTitle":"Pearls of Thought","sourceUrl":"https://www.gutenberg.org/cache/epub/26604/pg26604.txt","sourceSha256":"bd029a4490008a4ee6ad5738df5ba723c2ba850092f9e9042b32e0fe5540a2b6"}',
  '{"definitionId":"visited-saguaro","slot":1,"id":"historic-quotation/q-b1d7339dad754b72aaa954082ce2d901","text":"Human experience, like the stern-lights of a ship at sea, illumines only the path which we have passed over.","person":"Samuel Taylor Coleridge","personWikipediaUrl":"https://en.wikipedia.org/wiki/Samuel_Taylor_Coleridge","sourceTitle":"Book of Wise Sayings","sourceUrl":"https://www.gutenberg.org/cache/epub/21130/pg21130.txt","sourceSha256":"241fc6dd48bde0eaa24c2335184f566962f6a90e4b94a971b70d9600598a7fae"}',
  '{"definitionId":"visited-saguaro","slot":2,"id":"historic-quotation/q-e4ae665003633825f17eea92dd045599","text":"The expression of truth is simplicity.","person":"Seneca the Younger","personWikipediaUrl":"https://en.wikipedia.org/wiki/Seneca_the_Younger","sourceTitle":"Many Thoughts of Many Minds","sourceUrl":"https://www.gutenberg.org/cache/epub/17112/pg17112.txt","sourceSha256":"54ff4ba19eb9dd7b367d8f9893dd07fad81e5ce8b71bd5db5b38676c68221c21"}',
  '{"definitionId":"visited-sequoia","slot":1,"id":"historic-quotation/q-58f2d25d8f226a53dd0f79ad8b72554f","text":"In this world of change, naught which comes stays, and naught which goes is lost.","person":"Sophie Swetchine","personWikipediaUrl":"https://en.wikipedia.org/wiki/Sophie_Swetchine","sourceTitle":"Pearls of Thought","sourceUrl":"https://www.gutenberg.org/cache/epub/26604/pg26604.txt","sourceSha256":"bd029a4490008a4ee6ad5738df5ba723c2ba850092f9e9042b32e0fe5540a2b6"}',
  '{"definitionId":"visited-sequoia","slot":2,"id":"historic-quotation/q-3d21c56f825ff408b4a2ae1c975af341","text":"To love and to be loved is the greatest happiness of existence.","person":"Sydney Smith","personWikipediaUrl":"https://en.wikipedia.org/wiki/Sydney_Smith","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-shenandoah","slot":1,"id":"historic-quotation/q-e1a74203da3f8b1217f3b5e90232b0fb","text":"Knowledge advances by steps, and not by leaps.","person":"Thomas Babington Macaulay","personWikipediaUrl":"https://en.wikipedia.org/wiki/Thomas_Babington_Macaulay,_1st_Baron_Macaulay","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-shenandoah","slot":2,"id":"historic-quotation/q-f1011781e470906c9a3f1fc3ecf185ae","text":"Light that makes things seen makes some things invisible.","person":"Thomas Browne","personWikipediaUrl":"https://en.wikipedia.org/wiki/Thomas_Browne","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-theodore-roosevelt","slot":1,"id":"historic-quotation/q-703c5de82e702c454d4c2a2add0aca74","text":"If a book come from the heart, it will contrive to reach other hearts.","person":"Thomas Carlyle","personWikipediaUrl":"https://en.wikipedia.org/wiki/Thomas_Carlyle","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-theodore-roosevelt","slot":2,"id":"historic-quotation/q-d25e4c3aa7ee2725be8029d29a6f9327","text":"To carry care to bed is to sleep with a pack on your back.","person":"Thomas Chandler Haliburton","personWikipediaUrl":"https://en.wikipedia.org/wiki/Thomas_Chandler_Haliburton","sourceTitle":"Many Thoughts of Many Minds","sourceUrl":"https://www.gutenberg.org/cache/epub/17112/pg17112.txt","sourceSha256":"54ff4ba19eb9dd7b367d8f9893dd07fad81e5ce8b71bd5db5b38676c68221c21"}',
  '{"definitionId":"visited-virgin-islands","slot":1,"id":"historic-quotation/q-72ed1b1689f11daefd3d95aeb4ff1eba","text":"Contentment consisteth not in heaping more fuel, but in taking away some fire.","person":"Thomas Fuller","personWikipediaUrl":"https://en.wikipedia.org/wiki/Thomas_Fuller","sourceTitle":"Book of Wise Sayings","sourceUrl":"https://www.gutenberg.org/cache/epub/21130/pg21130.txt","sourceSha256":"241fc6dd48bde0eaa24c2335184f566962f6a90e4b94a971b70d9600598a7fae"}',
  '{"definitionId":"visited-virgin-islands","slot":2,"id":"historic-quotation/q-4278a9b9003aab4eefdb7a07ea73c797","text":"A vast multitude of pleasures, and these among the purest and the best, are superfluities, bits of good which are to all appearance unnecessary as inducements to live, and are, so to speak, thrown into the bargain of life.","person":"Thomas Henry Huxley","personWikipediaUrl":"https://en.wikipedia.org/wiki/Thomas_Henry_Huxley","sourceTitle":"Aphorisms and Reflections from the works of T. H. Huxley","sourceUrl":"https://www.gutenberg.org/cache/epub/35584/pg35584.txt","sourceSha256":"d43f042e4a0275e8903349a3fcfa4f5b992bcc186c536da1dd146391beb8e90b"}',
  '{"definitionId":"visited-voyageurs","slot":1,"id":"historic-quotation/q-9e11b71455b6a0c7790bee561431254d","text":"First think, and if thy thoughts approve thy will, Then speak, and after, what thou speak\'st fulfil.","person":"Thomas Randolph","personWikipediaUrl":"https://en.wikipedia.org/wiki/Thomas_Randolph_(poet)","sourceTitle":"Book of Wise Sayings","sourceUrl":"https://www.gutenberg.org/cache/epub/21130/pg21130.txt","sourceSha256":"241fc6dd48bde0eaa24c2335184f566962f6a90e4b94a971b70d9600598a7fae"}',
  '{"definitionId":"visited-voyageurs","slot":2,"id":"historic-quotation/q-abd0842fc8c4ddf147dd035a9035c42a","text":"As the purse is emptied the heart is filled.","person":"Victor Hugo","personWikipediaUrl":"https://en.wikipedia.org/wiki/Victor_Hugo","sourceTitle":"Many Thoughts of Many Minds","sourceUrl":"https://www.gutenberg.org/cache/epub/17112/pg17112.txt","sourceSha256":"54ff4ba19eb9dd7b367d8f9893dd07fad81e5ce8b71bd5db5b38676c68221c21"}',
  '{"definitionId":"visited-white-sands","slot":1,"id":"historic-quotation/q-35cba08e16cae815a0ea051ce9caaca1","text":"Love is a canvas furnished by Nature and embroidered by imagination.","person":"Voltaire","personWikipediaUrl":"https://en.wikipedia.org/wiki/Voltaire","sourceTitle":"Pearls of Thought","sourceUrl":"https://www.gutenberg.org/cache/epub/26604/pg26604.txt","sourceSha256":"bd029a4490008a4ee6ad5738df5ba723c2ba850092f9e9042b32e0fe5540a2b6"}',
  '{"definitionId":"visited-white-sands","slot":2,"id":"historic-quotation/q-07d584dd11a11a463a914023a550d36d","text":"Clear writers, like clear fountains, do not seem so deep as they are, the turbid looks most profound.","person":"Walter Savage Landor","personWikipediaUrl":"https://en.wikipedia.org/wiki/Walter_Savage_Landor","sourceTitle":"Pearls of Thought","sourceUrl":"https://www.gutenberg.org/cache/epub/26604/pg26604.txt","sourceSha256":"bd029a4490008a4ee6ad5738df5ba723c2ba850092f9e9042b32e0fe5540a2b6"}',
  '{"definitionId":"visited-wind-cave","slot":1,"id":"historic-quotation/q-631b7b1d335a5de103edc45bedc2be9e","text":"It is not the knowledge, but the use which is made of it that is productive of real benefit.","person":"Walter Scott","personWikipediaUrl":"https://en.wikipedia.org/wiki/Walter_Scott","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-wind-cave","slot":2,"id":"historic-quotation/q-88dedb398337c5f7f0ea7e1e6e56a973","text":"There is an emanation from the heart in genuine hospitality which cannot be described, but is immediately felt and puts the stranger at once at his ease.","person":"Washington Irving","personWikipediaUrl":"https://en.wikipedia.org/wiki/Washington_Irving","sourceTitle":"Many Thoughts of Many Minds","sourceUrl":"https://www.gutenberg.org/cache/epub/17112/pg17112.txt","sourceSha256":"54ff4ba19eb9dd7b367d8f9893dd07fad81e5ce8b71bd5db5b38676c68221c21"}',
  '{"definitionId":"visited-wrangell-st-elias","slot":1,"id":"historic-quotation/q-f33ba66509306ae86db944978b04b0c5","text":"When a work has a unity, it is as much so in a part as in the whole.","person":"William Blake","personWikipediaUrl":"https://en.wikipedia.org/wiki/William_Blake","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-wrangell-st-elias","slot":2,"id":"historic-quotation/q-4ebc43eb0c15720c1a0509ea603ab6b5","text":"Knowledge dwells in heads replete with thoughts of other men; Wisdom, in minds attentive to their own.","person":"William Cowper","personWikipediaUrl":"https://en.wikipedia.org/wiki/William_Cowper","sourceTitle":"Pearls of Thought","sourceUrl":"https://www.gutenberg.org/cache/epub/26604/pg26604.txt","sourceSha256":"bd029a4490008a4ee6ad5738df5ba723c2ba850092f9e9042b32e0fe5540a2b6"}',
  '{"definitionId":"visited-yellowstone","slot":1,"id":"historic-quotation/q-5b7c10af1c48abe9e20238c13919ad3b","text":"Account of one\'s reading is an account of one\'s life","person":"William Dean Howells","personWikipediaUrl":"https://en.wikipedia.org/wiki/William_Dean_Howells","sourceTitle":"Widger\'s Quotations from the Project Gutenberg Editions of the Works of William Dean Howells","sourceUrl":"https://www.gutenberg.org/cache/epub/3483/pg3483.txt","sourceSha256":"5b190a7175e291dfd07d8ebcd78f596fa29e2b2127da71cad1d4bc81cbdc2a55"}',
  '{"definitionId":"visited-yellowstone","slot":2,"id":"historic-quotation/q-69102fd4fac3cdba8f5d07b71ab616d8","text":"Difficulties are meant to rouse, not discourage.","person":"William Ellery Channing","personWikipediaUrl":"https://en.wikipedia.org/wiki/William_Ellery_Channing","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-zion","slot":1,"id":"historic-quotation/q-6d9d28927fd4984d50f9ec88cc71c13e","text":"Simplicity of character is the natural result of profound thought.","person":"William Hazlitt","personWikipediaUrl":"https://en.wikipedia.org/wiki/William_Hazlitt","sourceTitle":"Book of Wise Sayings","sourceUrl":"https://www.gutenberg.org/cache/epub/21130/pg21130.txt","sourceSha256":"241fc6dd48bde0eaa24c2335184f566962f6a90e4b94a971b70d9600598a7fae"}',
  '{"definitionId":"visited-zion","slot":2,"id":"historic-quotation/q-cf152a927e1752c77932aa43a05372c7","text":"The two most engaging powers of an author are to make new things familiar, and familiar things new.","person":"William Makepeace Thackeray","personWikipediaUrl":"https://en.wikipedia.org/wiki/William_Makepeace_Thackeray","sourceTitle":"Many Thoughts of Many Minds","sourceUrl":"https://www.gutenberg.org/cache/epub/17112/pg17112.txt","sourceSha256":"54ff4ba19eb9dd7b367d8f9893dd07fad81e5ce8b71bd5db5b38676c68221c21"}',
  '{"definitionId":"visited-all-us-national-parks","slot":1,"id":"historic-quotation/q-25b559a7f9e1c6a506d21b69944c8cb7","text":"Knowledge is the Treasure, but Judgment the Treasurer of a Wise Man.","person":"William Penn","personWikipediaUrl":"https://en.wikipedia.org/wiki/William_Penn","sourceTitle":"Some Fruits of Solitude in Reflections and Maxims","sourceUrl":"https://sourcebooks.fordham.edu/mod/1682penn-solitude.asp","sourceSha256":"d7f87b937ceaff9bd73ae75a7a3ea33a36a16b97f4e213e5759da7fabbb80438"}',
  '{"definitionId":"visited-all-us-national-parks","slot":2,"id":"historic-quotation/q-17f088c86ce9b03665e6b16cb177a73e","text":"As soon go kindle fire with snow, as seek to quench the fire of love with words.","person":"William Shakespeare","personWikipediaUrl":"https://en.wikipedia.org/wiki/William_Shakespeare","sourceTitle":"Pearls of Thought","sourceUrl":"https://www.gutenberg.org/cache/epub/26604/pg26604.txt","sourceSha256":"bd029a4490008a4ee6ad5738df5ba723c2ba850092f9e9042b32e0fe5540a2b6"}',
  '{"definitionId":"visited-us-state-01","slot":1,"id":"historic-quotation/q-1f6b987d51adf918110aba1d47a24992","text":"Wisdom is ofttimes nearer when we stoop Than when we soar.","person":"William Wordsworth","personWikipediaUrl":"https://en.wikipedia.org/wiki/William_Wordsworth","sourceTitle":"Many Thoughts of Many Minds","sourceUrl":"https://www.gutenberg.org/cache/epub/17112/pg17112.txt","sourceSha256":"54ff4ba19eb9dd7b367d8f9893dd07fad81e5ce8b71bd5db5b38676c68221c21"}',
  '{"definitionId":"visited-us-state-01","slot":2,"id":"historic-quotation/q-ef9606fe3440f4de942b8688a74da2e4","text":"Always do the very best you can.","person":"Abraham Lincoln","personWikipediaUrl":"https://en.wikipedia.org/wiki/Abraham_Lincoln","sourceTitle":"The Lincoln Year Book: Axioms and Aphorisms from the Great Emancipator","sourceUrl":"https://www.gutenberg.org/cache/epub/39204/pg39204.txt","sourceSha256":"1b6a3cb3664183e06d932e706117f3ca6721875c9564315ed22fe81897e3b4a2"}',
  '{"definitionId":"visited-us-state-02","slot":1,"id":"historic-quotation/q-a1e11da80733fe52d4877d29eee571f9","text":"Do not promise more than you can perform.","person":"Aesop","personWikipediaUrl":"https://en.wikipedia.org/wiki/Aesop","sourceTitle":"Aesop’s Fables: A New Translation (translated by V. S. Vernon Jones)","sourceUrl":"https://www.gutenberg.org/cache/epub/11339/pg11339.txt","sourceSha256":"0a2e7b971b00b76164071563e7e4bfa9cf962118ef67db9259020fc7c3b83602"}',
  '{"definitionId":"visited-us-state-02","slot":2,"id":"historic-quotation/q-e629b07fda523f194922cbd67362c1ec","text":"A decent boldness ever meets with friends.","person":"Alexander Pope","personWikipediaUrl":"https://en.wikipedia.org/wiki/Alexander_Pope","sourceTitle":"Familiar Quotations","sourceUrl":"https://www.gutenberg.org/cache/epub/27889/pg27889.txt","sourceSha256":"28da04fea3f40e0810b63102e30010479728230af8436f3f83ebdf8b32b9f1fb"}',
  '{"definitionId":"visited-us-state-04","slot":1,"id":"historic-quotation/q-b1507f37dcd14d6e8777d2f52a5ca381","text":"The most natural beauty in the world is honesty and moral truth.","person":"Anthony Ashley-Cooper, 3rd Earl of Shaftesbury","personWikipediaUrl":"https://en.wikipedia.org/wiki/Anthony_Ashley-Cooper,_3rd_Earl_of_Shaftesbury","sourceTitle":"Many Thoughts of Many Minds","sourceUrl":"https://www.gutenberg.org/cache/epub/17112/pg17112.txt","sourceSha256":"54ff4ba19eb9dd7b367d8f9893dd07fad81e5ce8b71bd5db5b38676c68221c21"}',
  '{"definitionId":"visited-us-state-04","slot":2,"id":"historic-quotation/q-beb69cc80b5b9a97ad8dae1bcd1325f9","text":"Our ideals are our better selves.","person":"Amos Bronson Alcott","personWikipediaUrl":"https://en.wikipedia.org/wiki/Amos_Bronson_Alcott","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-us-state-05","slot":1,"id":"historic-quotation/q-62e0d450493e83f8c75dc73ac04b2cb9","text":"The one exclusive sign of a thorough knowledge is the power of teaching.","person":"Aristotle","personWikipediaUrl":"https://en.wikipedia.org/wiki/Aristotle","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-us-state-05","slot":2,"id":"historic-quotation/q-7327ce5e6e44c2ac5b714019290e21e7","text":"Joy is a guest who generally comes uninvited.","person":"Arthur Schopenhauer","personWikipediaUrl":"https://en.wikipedia.org/wiki/Arthur_Schopenhauer","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-us-state-06","slot":1,"id":"historic-quotation/q-fefd4787bcdb534a35fe8e51949f5074","text":"Success is the child of audacity.","person":"Benjamin Disraeli","personWikipediaUrl":"https://en.wikipedia.org/wiki/Benjamin_Disraeli","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-us-state-06","slot":2,"id":"historic-quotation/q-22110f2f617c5a48683f72cb8ef1e93f","text":"A fine genius in his own country, is like gold in the mine.","person":"Benjamin Franklin","personWikipediaUrl":"https://en.wikipedia.org/wiki/Benjamin_Franklin","sourceTitle":"The Prefaces, Proverbs, and Poems of Benjamin Franklin","sourceUrl":"https://archive.org/download/prefacesproverbs00franrich/prefacesproverbs00franrich_djvu.txt","sourceSha256":"715b4de9f83af6844e62aeb157828c60ce662982a7b7e66ff2106cca2eb51858"}',
  '{"definitionId":"visited-us-state-08","slot":1,"id":"historic-quotation/q-a544ba4106764588248b66185180e659","text":"The last thing that we discover in writing a book is to know what to put at the beginning.","person":"Blaise Pascal","personWikipediaUrl":"https://en.wikipedia.org/wiki/Blaise_Pascal","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-us-state-08","slot":2,"id":"historic-quotation/q-8c295f52d88ecd191dcd109b48a98d6f","text":"In life, as in chess, forethought wins.","person":"Charles Buxton","personWikipediaUrl":"https://en.wikipedia.org/wiki/Charles_Buxton","sourceTitle":"Pearls of Thought","sourceUrl":"https://www.gutenberg.org/cache/epub/26604/pg26604.txt","sourceSha256":"bd029a4490008a4ee6ad5738df5ba723c2ba850092f9e9042b32e0fe5540a2b6"}',
  '{"definitionId":"visited-us-state-09","slot":1,"id":"historic-quotation/q-29b7736ac936d239e06b7a9457051a27","text":"We should labour to treat with ease of things that are difficult; with familiarity, of things that are novel; and with perspicuity, of things that are profound.","person":"Charles Caleb Colton","personWikipediaUrl":"https://en.wikipedia.org/wiki/Charles_Caleb_Colton","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-us-state-09","slot":2,"id":"historic-quotation/q-0fade861b240bc621405729016e71b88","text":"A day wasted on others is not wasted on one\'s self.","person":"Charles Dickens","personWikipediaUrl":"https://en.wikipedia.org/wiki/Charles_Dickens","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-us-state-10","slot":1,"id":"historic-quotation/q-dd390aaa56f40d71f870ecc260e4de51","text":"Do not habitually postpone that season of happiness","person":"Charles Dudley Warner","personWikipediaUrl":"https://en.wikipedia.org/wiki/Charles_Dudley_Warner","sourceTitle":"Quotations from the Project Gutenberg Editions of the Works of Charles Dudley Warner","sourceUrl":"https://www.gutenberg.org/cache/epub/3471/pg3471.txt","sourceSha256":"29ea89b07f35cc0adf1d31a507a5bff5c564243cdc62d45fb26baf54a807d3fe"}',
  '{"definitionId":"visited-us-state-10","slot":2,"id":"historic-quotation/q-53264d1f86128d8fb97ace3e881bf6c3","text":"The light in the world comes principally from two sources,--the sun, and the student\'s lamp.","person":"Christian Nestell Bovee","personWikipediaUrl":"https://en.wikipedia.org/wiki/Christian_Nestell_Bovee","sourceTitle":"Many Thoughts of Many Minds","sourceUrl":"https://www.gutenberg.org/cache/epub/17112/pg17112.txt","sourceSha256":"54ff4ba19eb9dd7b367d8f9893dd07fad81e5ce8b71bd5db5b38676c68221c21"}',
  '{"definitionId":"visited-us-state-12","slot":1,"id":"historic-quotation/q-cb59ba1a44faf58437bfc4d21ebdd3f8","text":"Strength and courage, simplicity and modesty are akin to love.","person":"Confucius","personWikipediaUrl":"https://en.wikipedia.org/wiki/Confucius","sourceTitle":"The Sayings of Confucius","sourceUrl":"https://www.gutenberg.org/cache/epub/24055/pg24055.txt","sourceSha256":"dfa209bdf6f902937fda12d487635d95f72285c0a433e3cf8e7bfe2e8e9c8be8"}',
  '{"definitionId":"visited-us-state-12","slot":2,"id":"historic-quotation/q-587fc751cc26de757ac0b03d5a73a85d","text":"The human race is in the best condition when it has the greatest degree of liberty.","person":"Dante Alighieri","personWikipediaUrl":"https://en.wikipedia.org/wiki/Dante_Alighieri","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-us-state-13","slot":1,"id":"historic-quotation/q-b5a58b8827872b47166d8199d0c20f3b","text":"The march of the human mind is slow.","person":"Edmund Burke","personWikipediaUrl":"https://en.wikipedia.org/wiki/Edmund_Burke","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-us-state-13","slot":2,"id":"historic-quotation/q-0793daa262fdc2e7d35fd52f854f83a3","text":"A couplet of verse, a period of prose, may cling to the rock of ages as a shell that survives a deluge.","person":"Edward Bulwer-Lytton","personWikipediaUrl":"https://en.wikipedia.org/wiki/Edward_Bulwer-Lytton","sourceTitle":"Pearls of Thought","sourceUrl":"https://www.gutenberg.org/cache/epub/26604/pg26604.txt","sourceSha256":"bd029a4490008a4ee6ad5738df5ba723c2ba850092f9e9042b32e0fe5540a2b6"}',
  '{"definitionId":"visited-us-state-15","slot":1,"id":"historic-quotation/q-ffebdd109d02d64ffc84b6334f0f0ab3","text":"Thoughts shut up want air, and spoil like bales unopened to the sun.","person":"Edward Young","personWikipediaUrl":"https://en.wikipedia.org/wiki/Edward_Young","sourceTitle":"Pearls of Thought","sourceUrl":"https://www.gutenberg.org/cache/epub/26604/pg26604.txt","sourceSha256":"bd029a4490008a4ee6ad5738df5ba723c2ba850092f9e9042b32e0fe5540a2b6"}',
  '{"definitionId":"visited-us-state-15","slot":2,"id":"historic-quotation/q-bf044e6e7a9cb0c99f8b883a96429535","text":"Truth is the root, but human sympathy is the flower of practical life.","person":"Edwin Hubbell Chapin","personWikipediaUrl":"https://en.wikipedia.org/wiki/Edwin_Hubbell_Chapin","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-us-state-16","slot":1,"id":"historic-quotation/q-ed9a3882322047bb2913d56cf95a8032","text":"An epigram often flashes light into regions where reason shines but dimly.","person":"Edwin Percy Whipple","personWikipediaUrl":"https://en.wikipedia.org/wiki/Edwin_Percy_Whipple","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-us-state-16","slot":2,"id":"historic-quotation/q-bc0854ae89a1c74b68d46c91fc0db1d9","text":"No pleasure is comparable to the standing upon the vantage-ground of truth.","person":"Francis Bacon","personWikipediaUrl":"https://en.wikipedia.org/wiki/Francis_Bacon","sourceTitle":"Familiar Quotations","sourceUrl":"https://www.gutenberg.org/cache/epub/27889/pg27889.txt","sourceSha256":"28da04fea3f40e0810b63102e30010479728230af8436f3f83ebdf8b32b9f1fb"}',
  '{"definitionId":"visited-us-state-17","slot":1,"id":"historic-quotation/q-65d19c276f4e1cb5b9daf8f2120835ee","text":"The last perfection of our faculties is that their activity, without ceasing to be sure and earnest, become sport.","person":"Friedrich Schiller","personWikipediaUrl":"https://en.wikipedia.org/wiki/Friedrich_Schiller","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-us-state-17","slot":2,"id":"historic-quotation/q-c753cdf32939a4c6c9580abff67c291a","text":"Our deeds determine us, as much as we determine our deeds.","person":"George Eliot","personWikipediaUrl":"https://en.wikipedia.org/wiki/George_Eliot","sourceTitle":"Pearls of Thought","sourceUrl":"https://www.gutenberg.org/cache/epub/26604/pg26604.txt","sourceSha256":"bd029a4490008a4ee6ad5738df5ba723c2ba850092f9e9042b32e0fe5540a2b6"}',
  '{"definitionId":"visited-us-state-18","slot":1,"id":"historic-quotation/q-34ccd578c0535157e213d37fe54502a4","text":"Men of great genius and large heart sow the seeds of a new degree of progress in the world, but they bear fruit only after many years.","person":"Giuseppe Mazzini","personWikipediaUrl":"https://en.wikipedia.org/wiki/Giuseppe_Mazzini","sourceTitle":"Pearls of Thought","sourceUrl":"https://www.gutenberg.org/cache/epub/26604/pg26604.txt","sourceSha256":"bd029a4490008a4ee6ad5738df5ba723c2ba850092f9e9042b32e0fe5540a2b6"}',
  '{"definitionId":"visited-us-state-18","slot":2,"id":"historic-quotation/q-3a16503893bfa6932dbd428008011dd8","text":"The only true principle for humanity is justice.","person":"Henri-Frédéric Amiel","personWikipediaUrl":"https://en.wikipedia.org/wiki/Henri-Fr%C3%A9d%C3%A9ric_Amiel","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-us-state-19","slot":1,"id":"historic-quotation/q-c8155255213345e8ff81d85e8d9e962e","text":"If one advances confidently in the direction of his dreams, and endeavours to live the life which he has imagined, he will meet with a success unexpected in common hours.","person":"Henry David Thoreau","personWikipediaUrl":"https://en.wikipedia.org/wiki/Henry_David_Thoreau","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-us-state-19","slot":2,"id":"historic-quotation/q-f1c226e0e539add5cf5d9f58947225c9","text":"Genius either discovers new materials of nature, or combines the known with novelty.","person":"Henry Fuseli","personWikipediaUrl":"https://en.wikipedia.org/wiki/Henry_Fuseli","sourceTitle":"The Life and Writings of Henry Fuseli, Volume 3: Aphorisms, Chiefly Relative to the Fine Arts","sourceUrl":"https://www.gutenberg.org/cache/epub/40474/pg40474.txt","sourceSha256":"0c3311df36f322386e02996cf5a17ecaf97f021d721ddc286ea66f7ecfa03fea"}',
  '{"definitionId":"visited-us-state-20","slot":1,"id":"historic-quotation/q-012144eaeb44825d7e159d1424455334","text":"To simplify complications is, in all branches of knowledge, the first essential of success.","person":"Henry Thomas Buckle","personWikipediaUrl":"https://en.wikipedia.org/wiki/Henry_Thomas_Buckle","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-us-state-20","slot":2,"id":"historic-quotation/q-b1c94f5d3b24605b3c998291f4cd0bf6","text":"A word that has been said may be unsaid: it is but air. But when a deed is done, it cannot be undone, nor can our thoughts reach out to all the mischiefs that may follow.","person":"Henry Wadsworth Longfellow","personWikipediaUrl":"https://en.wikipedia.org/wiki/Henry_Wadsworth_Longfellow","sourceTitle":"Pearls of Thought","sourceUrl":"https://www.gutenberg.org/cache/epub/26604/pg26604.txt","sourceSha256":"bd029a4490008a4ee6ad5738df5ba723c2ba850092f9e9042b32e0fe5540a2b6"}',
  '{"definitionId":"visited-us-state-21","slot":1,"id":"historic-quotation/q-7ff6da7a3c757c1705b1fa52b2a47796","text":"Greatness lies not in being strong, but in the right using of strength.","person":"Henry Ward Beecher","personWikipediaUrl":"https://en.wikipedia.org/wiki/Henry_Ward_Beecher","sourceTitle":"Pearls of Thought","sourceUrl":"https://www.gutenberg.org/cache/epub/26604/pg26604.txt","sourceSha256":"bd029a4490008a4ee6ad5738df5ba723c2ba850092f9e9042b32e0fe5540a2b6"}',
  '{"definitionId":"visited-us-state-21","slot":2,"id":"historic-quotation/q-dd03c9a7fcfe6facaae36a4020c19530","text":"Those who bring sunshine to the lives of others cannot keep it from themselves.","person":"J. M. Barrie","personWikipediaUrl":"https://en.wikipedia.org/wiki/J._M._Barrie","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-us-state-22","slot":1,"id":"historic-quotation/q-09b64b538fa00babff145cd9f45428bc","text":"The poet\'s heart is an unlighted torch, which gives no help to his footsteps till love has touched it with flame.","person":"James Russell Lowell","personWikipediaUrl":"https://en.wikipedia.org/wiki/James_Russell_Lowell","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-us-state-22","slot":2,"id":"historic-quotation/q-1c5c91f79f65b5a4636088c963cd545a","text":"The pleasure we feel in criticising robs us of that of being deeply moved by very beautiful things.","person":"Jean de La Bruyère","personWikipediaUrl":"https://en.wikipedia.org/wiki/Jean_de_La_Bruy%C3%A8re","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-us-state-23","slot":1,"id":"historic-quotation/q-0abde458c299385c29c230ea595da518","text":"Individuality is everywhere to be spared and respected as the root of everything good.","person":"Jean Paul","personWikipediaUrl":"https://en.wikipedia.org/wiki/Jean_Paul","sourceTitle":"Pearls of Thought","sourceUrl":"https://www.gutenberg.org/cache/epub/26604/pg26604.txt","sourceSha256":"bd029a4490008a4ee6ad5738df5ba723c2ba850092f9e9042b32e0fe5540a2b6"}',
  '{"definitionId":"visited-us-state-23","slot":2,"id":"historic-quotation/q-f3a1815bb592f125537aa69e7baa3e8b","text":"There is no true action without will.","person":"Jean-Jacques Rousseau","personWikipediaUrl":"https://en.wikipedia.org/wiki/Jean-Jacques_Rousseau","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-us-state-24","slot":1,"id":"historic-quotation/q-693aa9e92affcb2f00b471791efe7140","text":"An absent friend gives us friendly company when we are well assured of his happiness.","person":"Johann Wolfgang von Goethe","personWikipediaUrl":"https://en.wikipedia.org/wiki/Johann_Wolfgang_von_Goethe","sourceTitle":"Book of Wise Sayings","sourceUrl":"https://www.gutenberg.org/cache/epub/21130/pg21130.txt","sourceSha256":"241fc6dd48bde0eaa24c2335184f566962f6a90e4b94a971b70d9600598a7fae"}',
  '{"definitionId":"visited-us-state-24","slot":2,"id":"historic-quotation/q-af8d6169daf97be4c9f8357aa9ce2253","text":"The only fence against the world is a thorough knowledge of it.","person":"John Locke","personWikipediaUrl":"https://en.wikipedia.org/wiki/John_Locke","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-us-state-25","slot":1,"id":"historic-quotation/q-cab1f22ddcb32e2f0107f9f31dc71356","text":"A grateful mind By owing owes not, but still pays, at once Indebted and discharg\'d.","person":"John Milton","personWikipediaUrl":"https://en.wikipedia.org/wiki/John_Milton","sourceTitle":"Familiar Quotations","sourceUrl":"https://www.gutenberg.org/cache/epub/27889/pg27889.txt","sourceSha256":"28da04fea3f40e0810b63102e30010479728230af8436f3f83ebdf8b32b9f1fb"}',
  '{"definitionId":"visited-us-state-25","slot":2,"id":"historic-quotation/q-235bedaeea85e34a002acb653b964079","text":"The point is not that men should have a great many books, but that they should have the right ones, and that they should use those that they have.","person":"John Morley","personWikipediaUrl":"https://en.wikipedia.org/wiki/John_Morley","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-us-state-26","slot":1,"id":"historic-quotation/q-006e21120a45c54f36b0d203315bfa9c","text":"The entire object of true education is to make people not merely do the right things, but enjoy the right things.","person":"John Ruskin","personWikipediaUrl":"https://en.wikipedia.org/wiki/John_Ruskin","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-us-state-26","slot":2,"id":"historic-quotation/q-1986270ad0a93daaaa5825d61145f089","text":"Where truth is not at the bottom, Nature will always be endeavouring to return, and will peep out and betray herself one time or other.","person":"John Tillotson","personWikipediaUrl":"https://en.wikipedia.org/wiki/John_Tillotson","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-us-state-27","slot":1,"id":"historic-quotation/q-20d3817d8bbac96c8c60d7ee9768cf34","text":"Fully to understand a grand and beautiful thought requires, perhaps, as much time as to conceive it.","person":"Joseph Joubert","personWikipediaUrl":"https://en.wikipedia.org/wiki/Joseph_Joubert","sourceTitle":"Pearls of Thought","sourceUrl":"https://www.gutenberg.org/cache/epub/26604/pg26604.txt","sourceSha256":"bd029a4490008a4ee6ad5738df5ba723c2ba850092f9e9042b32e0fe5540a2b6"}',
  '{"definitionId":"visited-us-state-27","slot":2,"id":"historic-quotation/q-faca261456a0ce8bfbbeda9d6fda28bc","text":"Bountiful nature has provided that in all parts of the world you will find something to imitate.","person":"Leonardo da Vinci","personWikipediaUrl":"https://en.wikipedia.org/wiki/Leonardo_da_Vinci","sourceTitle":"Thoughts on Art and Life","sourceUrl":"https://www.gutenberg.org/cache/epub/29904/pg29904.txt","sourceSha256":"323f8893f03432a5b17a3f83ef698d1369a93dce41bdb16176653e85ba1a2c66"}',
  '{"definitionId":"visited-us-state-28","slot":1,"id":"historic-quotation/q-498e8b8477faedeae66595a04fac4609","text":"\'T is strange, but true; for truth is always strange,-- Stranger than fiction.","person":"Lord Byron","personWikipediaUrl":"https://en.wikipedia.org/wiki/Lord_Byron","sourceTitle":"Familiar Quotations","sourceUrl":"https://www.gutenberg.org/cache/epub/27889/pg27889.txt","sourceSha256":"28da04fea3f40e0810b63102e30010479728230af8436f3f83ebdf8b32b9f1fb"}',
  '{"definitionId":"visited-us-state-28","slot":2,"id":"historic-quotation/q-bb9bfa89c0997a2c671c8f922b2823bb","text":"You must rouse in men a consciousness of their own prudence and strength, if you would raise their character.","person":"Luc de Clapiers, marquis de Vauvenargues","personWikipediaUrl":"https://en.wikipedia.org/wiki/Luc_de_Clapiers,_marquis_de_Vauvenargues","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-us-state-29","slot":1,"id":"historic-quotation/q-a484d40b43f051f7e6e4a68f35da640c","text":"Accustom thyself to attend carefully to what is said by another, and as much as it is possible, be in the speaker’s mind.","person":"Marcus Aurelius","personWikipediaUrl":"https://en.wikipedia.org/wiki/Marcus_Aurelius","sourceTitle":"Thoughts of Marcus Aurelius (George Long translation)","sourceUrl":"https://www.gutenberg.org/cache/epub/6920/pg6920.txt","sourceSha256":"8e7b98cf8b079ed5a5280560939240707e210e923751de4232bba007f70b7b4e"}',
  '{"definitionId":"visited-us-state-29","slot":2,"id":"historic-quotation/q-0a740b373f7ba647f5b3c57a95107e92","text":"Genius is the gold in the mine—education the miner who elicits it.","person":"Marguerite Gardiner, Countess of Blessington","personWikipediaUrl":"https://en.wikipedia.org/wiki/Marguerite_Gardiner,_Countess_of_Blessington","sourceTitle":"Desultory Thoughts and Reflections","sourceUrl":"https://www.gutenberg.org/cache/epub/75737/pg75737.txt","sourceSha256":"9261723ed516a715c977bee43c07f00e79fd6448012f2555b9ee5de340ed031a"}',
  '{"definitionId":"visited-us-state-30","slot":1,"id":"historic-quotation/q-b0180ad0ddd561b69432f4391bbd6787","text":"Admiration is the foundation of all philosophy","person":"Michel de Montaigne","personWikipediaUrl":"https://en.wikipedia.org/wiki/Michel_de_Montaigne","sourceTitle":"Widger\'s Quotations from the Project Gutenberg Editions of the Works of Montaigne","sourceUrl":"https://www.gutenberg.org/cache/epub/3661/pg3661.txt","sourceSha256":"8967e5fa2bd702eae39585cc9e7a0e248ad041ba38b3a20fe31265b579b4e40e"}',
  '{"definitionId":"visited-us-state-30","slot":2,"id":"historic-quotation/q-b2ac4c448b30ec8820dff4395e352c05","text":"Tolerance is the only real test of civilization.","person":"Arthur Helps","personWikipediaUrl":"https://en.wikipedia.org/wiki/Arthur_Helps","sourceTitle":"Many Thoughts of Many Minds","sourceUrl":"https://www.gutenberg.org/cache/epub/17112/pg17112.txt","sourceSha256":"54ff4ba19eb9dd7b367d8f9893dd07fad81e5ce8b71bd5db5b38676c68221c21"}',
  '{"definitionId":"visited-us-state-31","slot":1,"id":"historic-quotation/q-dd6c204e4e25aa269cb712bcd4f1bef8","text":"To become properly acquainted with a truth, we must first have disbelieved it and disputed against it.","person":"Novalis","personWikipediaUrl":"https://en.wikipedia.org/wiki/Novalis","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-us-state-31","slot":2,"id":"historic-quotation/q-c91fc5db666bd2e16d12182142c9e123","text":"The man who can thank himself alone for the happiness he enjoys is truly blest.","person":"Oliver Goldsmith","personWikipediaUrl":"https://en.wikipedia.org/wiki/Oliver_Goldsmith","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-us-state-32","slot":1,"id":"historic-quotation/q-817f4c6b1974a321467a259c18362f17","text":"Endure philosophically what we cannot help","person":"Oliver Wendell Holmes Sr.","personWikipediaUrl":"https://en.wikipedia.org/wiki/Oliver_Wendell_Holmes_Sr.","sourceTitle":"Widger\'s Quotations from the Project Gutenberg Editions of the Works of Oliver W. Holmes, Sr.","sourceUrl":"https://www.gutenberg.org/cache/epub/3493/pg3493.txt","sourceSha256":"5555b810cf767c77ffddf10242048512a01bac723f1f624a791e422819e66feb"}',
  '{"definitionId":"visited-us-state-32","slot":2,"id":"historic-quotation/q-cf358c381910a9528184b07fec8996c0","text":"It is the spectator and not life that art really mirrors.","person":"Oscar Wilde","personWikipediaUrl":"https://en.wikipedia.org/wiki/Oscar_Wilde","sourceTitle":"Miscellaneous Aphorisms","sourceUrl":"https://www.gutenberg.org/cache/epub/33979/pg33979.txt","sourceSha256":"b2f26f9cca110780f4fcfe08aa5159f31306e6fe66c27d474dfdc5e95e40dfbf"}',
  '{"definitionId":"visited-us-state-33","slot":1,"id":"historic-quotation/q-e631d04d796b9cf78695b36c3debcf10","text":"Literature, like virtue, is its own reward.","person":"Philip Stanhope, 4th Earl of Chesterfield","personWikipediaUrl":"https://en.wikipedia.org/wiki/Philip_Stanhope,_4th_Earl_of_Chesterfield","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-us-state-33","slot":2,"id":"historic-quotation/q-ccd78854e1528e3ec285b9433d703cc6","text":"Rest is the sweet sauce of labour.","person":"Plutarch","personWikipediaUrl":"https://en.wikipedia.org/wiki/Plutarch","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-us-state-34","slot":1,"id":"historic-quotation/q-99950d54a39156dfa8477116057b0924","text":"A kindness should be received in the spirit that prompted it.","person":"Publilius Syrus","personWikipediaUrl":"https://en.wikipedia.org/wiki/Publilius_Syrus","sourceTitle":"The Moral Sayings of Publius Syrus, a Roman Slave","sourceUrl":"https://en.wikisource.org/wiki/The_Moral_Sayings_of_Publius_Syrus%2C_A_Roman_Slave?printable=yes","sourceSha256":"155e6832121547772bf11fa24feb36883a3b392cdb09101183929fe15cc43973"}',
  '{"definitionId":"visited-us-state-34","slot":2,"id":"historic-quotation/q-9fc34b94b19b2ab3a04c6d0f25c9543d","text":"Life finds its wealth by the claims of the world, and its worth by the claims of love.","person":"Rabindranath Tagore","personWikipediaUrl":"https://en.wikipedia.org/wiki/Rabindranath_Tagore","sourceTitle":"Stray Birds","sourceUrl":"https://www.gutenberg.org/cache/epub/6524/pg6524.txt","sourceSha256":"b8ad6f2827cb2b8496e386e583c93d6a4ce2525a24887d03ca361f5253eb5f9f"}',
  '{"definitionId":"visited-us-state-35","slot":1,"id":"historic-quotation/q-533409b2dead0fda9d25b84188354158","text":"All history becomes subjective; in other words, there is properly no History; only Biography.","person":"Ralph Waldo Emerson","personWikipediaUrl":"https://en.wikipedia.org/wiki/Ralph_Waldo_Emerson","sourceTitle":"The Wisdom of Ralph Waldo Emerson: Being Extracts from His Prose and Verse","sourceUrl":"https://archive.org/download/wisdomralphwald00parkgoog/wisdomralphwald00parkgoog_djvu.txt","sourceSha256":"325b25b72d66c0d6cff42367ad492b26cab54375e8eaaa6e2e51830e0f639a00"}',
  '{"definitionId":"visited-us-state-35","slot":2,"id":"historic-quotation/q-253845e9327940acac54ae0738d12d9d","text":"Hope springs exulting on triumphant wing.","person":"Robert Burns","personWikipediaUrl":"https://en.wikipedia.org/wiki/Robert_Burns","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-us-state-36","slot":1,"id":"historic-quotation/q-900ec7c8374c101699da0492bc4df6e3","text":"The shortest and the surest way to prove a work possible is strenuously to set about it; and no wonder if that proves it possible that for the most part makes it so.","person":"Robert South","personWikipediaUrl":"https://en.wikipedia.org/wiki/Robert_South_(priest)","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-us-state-36","slot":2,"id":"historic-quotation/q-63f3c2d53b5577e6e8bbc4f90156baa2","text":"The true, strong, and sound mind is the mind that can embrace equally great things and small.","person":"Samuel Johnson","personWikipediaUrl":"https://en.wikipedia.org/wiki/Samuel_Johnson","sourceTitle":"Familiar Quotations","sourceUrl":"https://www.gutenberg.org/cache/epub/27889/pg27889.txt","sourceSha256":"28da04fea3f40e0810b63102e30010479728230af8436f3f83ebdf8b32b9f1fb"}',
  '{"definitionId":"visited-us-state-37","slot":1,"id":"historic-quotation/q-58b4e6b61cac051fd2672372e82d8656","text":"Common sense in an uncommon degree is what the world calls wisdom.","person":"Samuel Taylor Coleridge","personWikipediaUrl":"https://en.wikipedia.org/wiki/Samuel_Taylor_Coleridge","sourceTitle":"Pearls of Thought","sourceUrl":"https://www.gutenberg.org/cache/epub/26604/pg26604.txt","sourceSha256":"bd029a4490008a4ee6ad5738df5ba723c2ba850092f9e9042b32e0fe5540a2b6"}',
  '{"definitionId":"visited-us-state-37","slot":2,"id":"historic-quotation/q-035816c821be18de3b987f70f92b187e","text":"Time is a wave which never murmurs, because there is no obstacle to its flow.","person":"Sophie Swetchine","personWikipediaUrl":"https://en.wikipedia.org/wiki/Sophie_Swetchine","sourceTitle":"Pearls of Thought","sourceUrl":"https://www.gutenberg.org/cache/epub/26604/pg26604.txt","sourceSha256":"bd029a4490008a4ee6ad5738df5ba723c2ba850092f9e9042b32e0fe5540a2b6"}',
  '{"definitionId":"visited-us-state-38","slot":1,"id":"historic-quotation/q-e55caa94c442aa24ec284f30c45c6c27","text":"The hearts of men are their books, events are their tutors, great actions are their eloquence.","person":"Thomas Babington Macaulay","personWikipediaUrl":"https://en.wikipedia.org/wiki/Thomas_Babington_Macaulay,_1st_Baron_Macaulay","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-us-state-38","slot":2,"id":"historic-quotation/q-aab34cd88134c3553b36b0a1a57fad01","text":"The burning of a little straw may hide the stars of the sky; but the stars are there, and will reappear.","person":"Thomas Carlyle","personWikipediaUrl":"https://en.wikipedia.org/wiki/Thomas_Carlyle","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-us-state-39","slot":1,"id":"historic-quotation/q-0b4cf4284d439dd693f25d9d478dfa90","text":"Accuracy is the foundation of everything else.","person":"Thomas Henry Huxley","personWikipediaUrl":"https://en.wikipedia.org/wiki/Thomas_Henry_Huxley","sourceTitle":"Aphorisms and Reflections from the works of T. H. Huxley","sourceUrl":"https://www.gutenberg.org/cache/epub/35584/pg35584.txt","sourceSha256":"d43f042e4a0275e8903349a3fcfa4f5b992bcc186c536da1dd146391beb8e90b"}',
  '{"definitionId":"visited-us-state-39","slot":2,"id":"historic-quotation/q-3df9176b94d9f8802b00ba57d6ca5622","text":"Life is a flower of which love is the honey.","person":"Victor Hugo","personWikipediaUrl":"https://en.wikipedia.org/wiki/Victor_Hugo","sourceTitle":"Pearls of Thought","sourceUrl":"https://www.gutenberg.org/cache/epub/26604/pg26604.txt","sourceSha256":"bd029a4490008a4ee6ad5738df5ba723c2ba850092f9e9042b32e0fe5540a2b6"}',
  '{"definitionId":"visited-us-state-40","slot":1,"id":"historic-quotation/q-6f9004c1fda083725a1ce5e5e1767beb","text":"The more we have read, the more we have learned, the more we have meditated, the better conditioned we are to affirm that we know nothing.","person":"Voltaire","personWikipediaUrl":"https://en.wikipedia.org/wiki/Voltaire","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-us-state-40","slot":2,"id":"historic-quotation/q-313ecebd226fac6d6bfee4dda94166b7","text":"We are contented because we are happy, and not happy because we are contented.","person":"Walter Savage Landor","personWikipediaUrl":"https://en.wikipedia.org/wiki/Walter_Savage_Landor","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-us-state-41","slot":1,"id":"historic-quotation/q-6951893c13c4337602d3d91c1c446094","text":"The human mind is to be treated like a skein of ravelled silk, where you must cautiously secure one free end before you can make any progress in disentangling it.","person":"Walter Scott","personWikipediaUrl":"https://en.wikipedia.org/wiki/Walter_Scott","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-us-state-41","slot":2,"id":"historic-quotation/q-6756db6512ecb5bda09b7644ffc62b4e","text":"Sweet is the memory of distant friends! Like the mellow rays of the declining sun, it falls tenderly, yet sadly, on the heart.","person":"Washington Irving","personWikipediaUrl":"https://en.wikipedia.org/wiki/Washington_Irving","sourceTitle":"Pearls of Thought","sourceUrl":"https://www.gutenberg.org/cache/epub/26604/pg26604.txt","sourceSha256":"bd029a4490008a4ee6ad5738df5ba723c2ba850092f9e9042b32e0fe5540a2b6"}',
  '{"definitionId":"visited-us-state-42","slot":1,"id":"historic-quotation/q-188e8a9bc3768bfbb59c060937a77bd2","text":"Happiness depends, as Nature shows, Less on exterior things than most suppose.","person":"William Cowper","personWikipediaUrl":"https://en.wikipedia.org/wiki/William_Cowper","sourceTitle":"Familiar Quotations","sourceUrl":"https://www.gutenberg.org/cache/epub/27889/pg27889.txt","sourceSha256":"28da04fea3f40e0810b63102e30010479728230af8436f3f83ebdf8b32b9f1fb"}',
  '{"definitionId":"visited-us-state-42","slot":2,"id":"historic-quotation/q-06d4113b75fc2f72c77123824031e25d","text":"Let fiction cease to lie about life","person":"William Dean Howells","personWikipediaUrl":"https://en.wikipedia.org/wiki/William_Dean_Howells","sourceTitle":"Widger\'s Quotations from the Project Gutenberg Editions of the Works of William Dean Howells","sourceUrl":"https://www.gutenberg.org/cache/epub/3483/pg3483.txt","sourceSha256":"5b190a7175e291dfd07d8ebcd78f596fa29e2b2127da71cad1d4bc81cbdc2a55"}',
  '{"definitionId":"visited-us-state-44","slot":1,"id":"historic-quotation/q-59673e0b69c7cda6fddd3c1b8345b162","text":"The great hope of society is individual character.","person":"William Ellery Channing","personWikipediaUrl":"https://en.wikipedia.org/wiki/William_Ellery_Channing","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-us-state-44","slot":2,"id":"historic-quotation/q-59c10746534b7661352a2f623c49fa0c","text":"True modesty and true pride are much the same thing. Both consist in setting a just value on ourselves--neither more nor less.","person":"William Hazlitt","personWikipediaUrl":"https://en.wikipedia.org/wiki/William_Hazlitt","sourceTitle":"Book of Wise Sayings","sourceUrl":"https://www.gutenberg.org/cache/epub/21130/pg21130.txt","sourceSha256":"241fc6dd48bde0eaa24c2335184f566962f6a90e4b94a971b70d9600598a7fae"}',
  '{"definitionId":"visited-us-state-45","slot":1,"id":"historic-quotation/q-8e521b6311f9fc5c73c7402a5774f84e","text":"A good laugh is sunshine in a house.","person":"William Makepeace Thackeray","personWikipediaUrl":"https://en.wikipedia.org/wiki/William_Makepeace_Thackeray","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-us-state-45","slot":2,"id":"historic-quotation/q-f9e7c38e119981b8c83cb06b62430d8c","text":"We have a Call to do good, as often as we have the Power and Occasion.","person":"William Penn","personWikipediaUrl":"https://en.wikipedia.org/wiki/William_Penn","sourceTitle":"Some Fruits of Solitude in Reflections and Maxims","sourceUrl":"https://sourcebooks.fordham.edu/mod/1682penn-solitude.asp","sourceSha256":"d7f87b937ceaff9bd73ae75a7a3ea33a36a16b97f4e213e5759da7fabbb80438"}',
  '{"definitionId":"visited-us-state-46","slot":1,"id":"historic-quotation/q-284d81793a72886c73c1b5caeb7f206a","text":"Opportunity is rare, and a wise man will never let it go by him.","person":"Bayard Taylor","personWikipediaUrl":"https://en.wikipedia.org/wiki/Bayard_Taylor","sourceTitle":"Many Thoughts of Many Minds","sourceUrl":"https://www.gutenberg.org/cache/epub/17112/pg17112.txt","sourceSha256":"54ff4ba19eb9dd7b367d8f9893dd07fad81e5ce8b71bd5db5b38676c68221c21"}',
  '{"definitionId":"visited-us-state-46","slot":2,"id":"historic-quotation/q-340646ceadb61ffe419268d3733785f0","text":"The noble-minded dedicate themselves to the promotion of the happiness of others--even of those who injure them. True happiness consists in making happy.","person":"Bharavi","personWikipediaUrl":"https://en.wikipedia.org/wiki/Bharavi","sourceTitle":"Book of Wise Sayings: Selected Largely from Eastern Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/21130/pg21130.txt","sourceSha256":"241fc6dd48bde0eaa24c2335184f566962f6a90e4b94a971b70d9600598a7fae"}',
  '{"definitionId":"visited-us-state-47","slot":1,"id":"historic-quotation/q-756b8df7267601ef040b9a283298b79e","text":"By mutual concessions we should harmonize and act together.","person":"Abraham Lincoln","personWikipediaUrl":"https://en.wikipedia.org/wiki/Abraham_Lincoln","sourceTitle":"The Lincoln Year Book: Axioms and Aphorisms from the Great Emancipator","sourceUrl":"https://www.gutenberg.org/cache/epub/39204/pg39204.txt","sourceSha256":"1b6a3cb3664183e06d932e706117f3ca6721875c9564315ed22fe81897e3b4a2"}',
  '{"definitionId":"visited-us-state-47","slot":2,"id":"historic-quotation/q-8a4c4291a51b0c81840a7499867b4d65","text":"Example is better than precept.","person":"Aesop","personWikipediaUrl":"https://en.wikipedia.org/wiki/Aesop","sourceTitle":"Aesop’s Fables: A New Translation (translated by V. S. Vernon Jones)","sourceUrl":"https://www.gutenberg.org/cache/epub/11339/pg11339.txt","sourceSha256":"0a2e7b971b00b76164071563e7e4bfa9cf962118ef67db9259020fc7c3b83602"}',
  '{"definitionId":"visited-us-state-48","slot":1,"id":"historic-quotation/q-1624430dac4aa6493ade474a12e2e282","text":"Do good by stealth, and blush to find it fame.","person":"Alexander Pope","personWikipediaUrl":"https://en.wikipedia.org/wiki/Alexander_Pope","sourceTitle":"Familiar Quotations","sourceUrl":"https://www.gutenberg.org/cache/epub/27889/pg27889.txt","sourceSha256":"28da04fea3f40e0810b63102e30010479728230af8436f3f83ebdf8b32b9f1fb"}',
  '{"definitionId":"visited-us-state-48","slot":2,"id":"historic-quotation/q-ed6760a280f4477634d3e634cf34508f","text":"How dull it is to pause, to make an end, To rust unburnish\'d, not to shine in use,-- As tho\' to breathe were life!","person":"Alfred, Lord Tennyson","personWikipediaUrl":"https://en.wikipedia.org/wiki/Alfred,_Lord_Tennyson","sourceTitle":"Familiar Quotations","sourceUrl":"https://www.gutenberg.org/cache/epub/27889/pg27889.txt","sourceSha256":"28da04fea3f40e0810b63102e30010479728230af8436f3f83ebdf8b32b9f1fb"}',
  '{"definitionId":"visited-us-state-49","slot":1,"id":"historic-quotation/q-3287c4cbd25dcbfe7e873b215f5e4668","text":"Success is sweet; the sweeter if long delayed, and attained through manifold struggles and defeats.","person":"Amos Bronson Alcott","personWikipediaUrl":"https://en.wikipedia.org/wiki/Amos_Bronson_Alcott","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-us-state-49","slot":2,"id":"historic-quotation/q-28513e6fb8ebc8ccb94ef85c31b19572","text":"To be happy means to be sufficient for one\'s self.","person":"Aristotle","personWikipediaUrl":"https://en.wikipedia.org/wiki/Aristotle","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-us-state-50","slot":1,"id":"historic-quotation/q-d83bce4e60ac1972460ece5eff64ff4d","text":"The greatest achievements of the human mind are generally received at first with distrust.","person":"Arthur Schopenhauer","personWikipediaUrl":"https://en.wikipedia.org/wiki/Arthur_Schopenhauer","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-us-state-50","slot":2,"id":"historic-quotation/q-7507becc6e813d7c3c79dee7782b1ed9","text":"The secret of success is constancy to purpose.","person":"Benjamin Disraeli","personWikipediaUrl":"https://en.wikipedia.org/wiki/Benjamin_Disraeli","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-us-state-51","slot":1,"id":"historic-quotation/q-1bdbf34e7a2fa8824cd44d19d66011b3","text":"A good Example is the best Sermon.","person":"Benjamin Franklin","personWikipediaUrl":"https://en.wikipedia.org/wiki/Benjamin_Franklin","sourceTitle":"The Prefaces, Proverbs, and Poems of Benjamin Franklin","sourceUrl":"https://archive.org/download/prefacesproverbs00franrich/prefacesproverbs00franrich_djvu.txt","sourceSha256":"715b4de9f83af6844e62aeb157828c60ce662982a7b7e66ff2106cca2eb51858"}',
  '{"definitionId":"visited-us-state-51","slot":2,"id":"historic-quotation/q-889d3e4605c3011ffde3c9c228008935","text":"Success soon palls. The joyous time is when the breeze first strikes your sails, and the waters rustle under your bows.","person":"Charles Buxton","personWikipediaUrl":"https://en.wikipedia.org/wiki/Charles_Buxton","sourceTitle":"Pearls of Thought","sourceUrl":"https://www.gutenberg.org/cache/epub/26604/pg26604.txt","sourceSha256":"bd029a4490008a4ee6ad5738df5ba723c2ba850092f9e9042b32e0fe5540a2b6"}',
  '{"definitionId":"visited-us-state-53","slot":1,"id":"historic-quotation/q-c87fa5786b46182a565921a586874ccc","text":"Every traveller has a home of his own, and he learns to appreciate it the more from his wandering.","person":"Charles Dickens","personWikipediaUrl":"https://en.wikipedia.org/wiki/Charles_Dickens","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-us-state-53","slot":2,"id":"historic-quotation/q-7dae9f7c8e1e71e958d32f774b64bf11","text":"Happiness is an inner condition, not to be raced after","person":"Charles Dudley Warner","personWikipediaUrl":"https://en.wikipedia.org/wiki/Charles_Dudley_Warner","sourceTitle":"Quotations from the Project Gutenberg Editions of the Works of Charles Dudley Warner","sourceUrl":"https://www.gutenberg.org/cache/epub/3471/pg3471.txt","sourceSha256":"29ea89b07f35cc0adf1d31a507a5bff5c564243cdc62d45fb26baf54a807d3fe"}',
  '{"definitionId":"visited-us-state-54","slot":1,"id":"historic-quotation/q-b66ea173429bf93f3d76966b9c3303be","text":"It is our relation to circumstances that determines their influence over us. The same wind that carries one vessel into port may blow another off shore.","person":"Christian Nestell Bovee","personWikipediaUrl":"https://en.wikipedia.org/wiki/Christian_Nestell_Bovee","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-us-state-54","slot":2,"id":"historic-quotation/q-853e8152cc73c1afdb2dc642c308060f","text":"The only liberty that is valuable is a liberty connected with order.","person":"Edmund Burke","personWikipediaUrl":"https://en.wikipedia.org/wiki/Edmund_Burke","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-us-state-55","slot":1,"id":"historic-quotation/q-469db9bcd0656b0fda69c098a6e6cf50","text":"A mind once cultivated will not lie fallow for half an hour.","person":"Edward Bulwer-Lytton","personWikipediaUrl":"https://en.wikipedia.org/wiki/Edward_Bulwer-Lytton","sourceTitle":"Pearls of Thought","sourceUrl":"https://www.gutenberg.org/cache/epub/26604/pg26604.txt","sourceSha256":"bd029a4490008a4ee6ad5738df5ba723c2ba850092f9e9042b32e0fe5540a2b6"}',
  '{"definitionId":"visited-us-state-55","slot":2,"id":"historic-quotation/q-48952e44077a60e2265342824fc5516c","text":"Truth should be strenuous and bold; but the strongest things are not always the noisiest, as any one may see who compares scolding with logic.","person":"Edwin Hubbell Chapin","personWikipediaUrl":"https://en.wikipedia.org/wiki/Edwin_Hubbell_Chapin","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"visited-us-state-56","slot":1,"id":"historic-quotation/q-da543742eabf59f9dbd1fff4b897db38","text":"Some books are to be tasted, others to be swallowed, and some few to be chewed and digested.","person":"Francis Bacon","personWikipediaUrl":"https://en.wikipedia.org/wiki/Francis_Bacon","sourceTitle":"Familiar Quotations","sourceUrl":"https://www.gutenberg.org/cache/epub/27889/pg27889.txt","sourceSha256":"28da04fea3f40e0810b63102e30010479728230af8436f3f83ebdf8b32b9f1fb"}',
  '{"definitionId":"visited-us-state-56","slot":2,"id":"historic-quotation/q-03d07921ca8a45046cc209d89fbc1fd2","text":"The voice of the majority is no proof of justice.","person":"Friedrich Schiller","personWikipediaUrl":"https://en.wikipedia.org/wiki/Friedrich_Schiller","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"read-sapiens","slot":1,"id":"historic-quotation/q-5999217c6c1f8756beba30f8b88dc9b2","text":"The human soul is hospitable, and will entertain conflicting sentiments and contradictory opinions with much impartiality.","person":"George Eliot","personWikipediaUrl":"https://en.wikipedia.org/wiki/George_Eliot","sourceTitle":"Pearls of Thought","sourceUrl":"https://www.gutenberg.org/cache/epub/26604/pg26604.txt","sourceSha256":"bd029a4490008a4ee6ad5738df5ba723c2ba850092f9e9042b32e0fe5540a2b6"}',
  '{"definitionId":"read-sapiens","slot":2,"id":"historic-quotation/q-5c5c814f96d76297ea9906377ab23af6","text":"There is no respect for others without humility in one\'s self.","person":"Henri-Frédéric Amiel","personWikipediaUrl":"https://en.wikipedia.org/wiki/Henri-Fr%C3%A9d%C3%A9ric_Amiel","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"read-nineteen-eighty-four","slot":1,"id":"historic-quotation/q-97d3141989281f3fcb6a4591674c44d8","text":"There is never but one opportunity of a kind.","person":"Henry David Thoreau","personWikipediaUrl":"https://en.wikipedia.org/wiki/Henry_David_Thoreau","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"read-nineteen-eighty-four","slot":2,"id":"historic-quotation/q-10144a278992e3c0e9acd6a4af71e4d5","text":"Genius may adopt, but never steals.","person":"Henry Fuseli","personWikipediaUrl":"https://en.wikipedia.org/wiki/Henry_Fuseli","sourceTitle":"The Life and Writings of Henry Fuseli, Volume 3: Aphorisms, Chiefly Relative to the Fine Arts","sourceUrl":"https://www.gutenberg.org/cache/epub/40474/pg40474.txt","sourceSha256":"0c3311df36f322386e02996cf5a17ecaf97f021d721ddc286ea66f7ecfa03fea"}',
  '{"definitionId":"read-to-kill-a-mockingbird","slot":1,"id":"historic-quotation/q-5506eb88bd04b6d189994fef1b175b4f","text":"The talent of success is nothing more than doing what you can do well; and doing well whatever you do, without a thought of fame.","person":"Henry Wadsworth Longfellow","personWikipediaUrl":"https://en.wikipedia.org/wiki/Henry_Wadsworth_Longfellow","sourceTitle":"Pearls of Thought","sourceUrl":"https://www.gutenberg.org/cache/epub/26604/pg26604.txt","sourceSha256":"bd029a4490008a4ee6ad5738df5ba723c2ba850092f9e9042b32e0fe5540a2b6"}',
  '{"definitionId":"read-to-kill-a-mockingbird","slot":2,"id":"historic-quotation/q-ee617bbd61013913e08d7227f4bd5f6f","text":"Action is the right outlet of emotion.","person":"Henry Ward Beecher","personWikipediaUrl":"https://en.wikipedia.org/wiki/Henry_Ward_Beecher","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"read-the-great-gatsby","slot":1,"id":"historic-quotation/q-cf6862471b428618d2347023baf85e4d","text":"There is no good in arguing with the inevitable.","person":"James Russell Lowell","personWikipediaUrl":"https://en.wikipedia.org/wiki/James_Russell_Lowell","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"read-the-great-gatsby","slot":2,"id":"historic-quotation/q-958e6538a2f0805628a2cc14e89bfed4","text":"There is no road too long to the man who advances deliberately and without undue haste; there are no honours too distant to the man who prepares himself for them with patience.","person":"Jean de La Bruyère","personWikipediaUrl":"https://en.wikipedia.org/wiki/Jean_de_La_Bruy%C3%A8re","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"read-pride-and-prejudice","slot":1,"id":"historic-quotation/q-4f17ef8fa66470ae6fc639773a9801fa","text":"Never does a man portray his own character more vividly than in his manner of portraying another.","person":"Jean Paul","personWikipediaUrl":"https://en.wikipedia.org/wiki/Jean_Paul","sourceTitle":"Pearls of Thought","sourceUrl":"https://www.gutenberg.org/cache/epub/26604/pg26604.txt","sourceSha256":"bd029a4490008a4ee6ad5738df5ba723c2ba850092f9e9042b32e0fe5540a2b6"}',
  '{"definitionId":"read-pride-and-prejudice","slot":2,"id":"historic-quotation/q-30de3235b4bf35564b43fab93d51cc94","text":"We do not know what is really good or bad fortune.","person":"Jean-Jacques Rousseau","personWikipediaUrl":"https://en.wikipedia.org/wiki/Jean-Jacques_Rousseau","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"read-the-count-of-monte-cristo","slot":1,"id":"historic-quotation/q-80254bdf0865ee5af809ee0e16bee6ef","text":"Noble birth is an accident of fortune, noble actions characterise the great.","person":"Carlo Goldoni","personWikipediaUrl":"https://en.wikipedia.org/wiki/Carlo_Goldoni","sourceTitle":"Book of Wise Sayings: Selected Largely from Eastern Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/21130/pg21130.txt","sourceSha256":"241fc6dd48bde0eaa24c2335184f566962f6a90e4b94a971b70d9600598a7fae"}',
  '{"definitionId":"read-the-count-of-monte-cristo","slot":2,"id":"historic-quotation/q-7f659fc1c9e06c2de36885f53532596b","text":"We ought not, in general, to take the opinions of others upon trust, but to reason and judge for ourselves.","person":"John Locke","personWikipediaUrl":"https://en.wikipedia.org/wiki/John_Locke","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"read-the-odyssey","slot":1,"id":"historic-quotation/q-3866bc33b084278b02866266ea7f5d2c","text":"See golden days, fruitful of golden deeds, With joy and love triumphing.","person":"John Milton","personWikipediaUrl":"https://en.wikipedia.org/wiki/John_Milton","sourceTitle":"Familiar Quotations","sourceUrl":"https://www.gutenberg.org/cache/epub/27889/pg27889.txt","sourceSha256":"28da04fea3f40e0810b63102e30010479728230af8436f3f83ebdf8b32b9f1fb"}',
  '{"definitionId":"read-the-odyssey","slot":2,"id":"historic-quotation/q-0be82bb99548b57f49f47eeb7d03d67d","text":"You will find that most books worth reading once are worth reading twice.","person":"John Morley","personWikipediaUrl":"https://en.wikipedia.org/wiki/John_Morley","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"read-the-brothers-karamazov","slot":1,"id":"historic-quotation/q-ae81ae2d4141177d352dc283485bbff7","text":"The entire vitality of art depends upon its having for object either to state a true thing or adorn a serviceable one.","person":"John Ruskin","personWikipediaUrl":"https://en.wikipedia.org/wiki/John_Ruskin","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"read-the-brothers-karamazov","slot":2,"id":"historic-quotation/q-4cef97aa84248d190324bc7a5c7cf9d8","text":"Genius begins great works, labor alone finishes them.","person":"Joseph Joubert","personWikipediaUrl":"https://en.wikipedia.org/wiki/Joseph_Joubert","sourceTitle":"Pearls of Thought","sourceUrl":"https://www.gutenberg.org/cache/epub/26604/pg26604.txt","sourceSha256":"bd029a4490008a4ee6ad5738df5ba723c2ba850092f9e9042b32e0fe5540a2b6"}',
  '{"definitionId":"read-guns-germs-and-steel","slot":1,"id":"historic-quotation/q-f8ce94f4f131c43d34f9bdcd451b932c","text":"The water you touch in a river is the last of that which has gone, and the first of that which is coming: so it is with time present.","person":"Leonardo da Vinci","personWikipediaUrl":"https://en.wikipedia.org/wiki/Leonardo_da_Vinci","sourceTitle":"Thoughts on Art and Life","sourceUrl":"https://www.gutenberg.org/cache/epub/29904/pg29904.txt","sourceSha256":"323f8893f03432a5b17a3f83ef698d1369a93dce41bdb16176653e85ba1a2c66"}',
  '{"definitionId":"read-guns-germs-and-steel","slot":2,"id":"historic-quotation/q-cc4d32c9960dff09e3abe408342e1eb2","text":"There\'s a courage which grows out of fear.","person":"Lord Byron","personWikipediaUrl":"https://en.wikipedia.org/wiki/Lord_Byron","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"read-the-dawn-of-everything","slot":1,"id":"historic-quotation/q-d91083cae70ab6985a6f4f355cc97e6e","text":"If a thing is difficult to be accomplished by thyself, do not think that it is impossible for man: but if anything is possible for man and conformable to his nature, think that this can be attained by thyself too.","person":"Marcus Aurelius","personWikipediaUrl":"https://en.wikipedia.org/wiki/Marcus_Aurelius","sourceTitle":"Thoughts of Marcus Aurelius (George Long translation)","sourceUrl":"https://www.gutenberg.org/cache/epub/6920/pg6920.txt","sourceSha256":"8e7b98cf8b079ed5a5280560939240707e210e923751de4232bba007f70b7b4e"}',
  '{"definitionId":"read-the-dawn-of-everything","slot":2,"id":"historic-quotation/q-e0ada9706e72bebff8ead765f54a56dc","text":"Happiness consists, not in having much, but in being content with little.","person":"Marguerite Gardiner, Countess of Blessington","personWikipediaUrl":"https://en.wikipedia.org/wiki/Marguerite_Gardiner,_Countess_of_Blessington","sourceTitle":"Desultory Thoughts and Reflections","sourceUrl":"https://www.gutenberg.org/cache/epub/75737/pg75737.txt","sourceSha256":"9261723ed516a715c977bee43c07f00e79fd6448012f2555b9ee5de340ed031a"}',
  '{"definitionId":"read-the-silk-roads","slot":1,"id":"historic-quotation/q-a9ea568d391fef137f9961442bc3b68f","text":"Courtesy and good manners is a very necessary study","person":"Michel de Montaigne","personWikipediaUrl":"https://en.wikipedia.org/wiki/Michel_de_Montaigne","sourceTitle":"Widger\'s Quotations from the Project Gutenberg Editions of the Works of Montaigne","sourceUrl":"https://www.gutenberg.org/cache/epub/3661/pg3661.txt","sourceSha256":"8967e5fa2bd702eae39585cc9e7a0e248ad041ba38b3a20fe31265b579b4e40e"}',
  '{"definitionId":"read-the-silk-roads","slot":2,"id":"historic-quotation/q-558c61b17b6746fc234374381e17f84d","text":"The knowledge of thyself will preserve thee from vanity.","person":"Miguel de Cervantes","personWikipediaUrl":"https://en.wikipedia.org/wiki/Miguel_de_Cervantes","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"read-team-of-rivals","slot":1,"id":"historic-quotation/q-be1d74ee50a515ff671f21d9c66e4dad","text":"We should distinguish between laughter inspired by joy, and that which arises from mockery.","person":"Oliver Goldsmith","personWikipediaUrl":"https://en.wikipedia.org/wiki/Oliver_Goldsmith","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"read-team-of-rivals","slot":2,"id":"historic-quotation/q-97becd181903c4bf864e9f9473ee9f55","text":"Habit is a labor-saving invention","person":"Oliver Wendell Holmes Sr.","personWikipediaUrl":"https://en.wikipedia.org/wiki/Oliver_Wendell_Holmes_Sr.","sourceTitle":"Widger\'s Quotations from the Project Gutenberg Editions of the Works of Oliver W. Holmes, Sr.","sourceUrl":"https://www.gutenberg.org/cache/epub/3493/pg3493.txt","sourceSha256":"5555b810cf767c77ffddf10242048512a01bac723f1f624a791e422819e66feb"}',
  '{"definitionId":"read-the-warmth-of-other-suns","slot":1,"id":"historic-quotation/q-6d75b06e714dd194b2e3314f0b2720e6","text":"Sensations are the details that build up the stories of our lives.","person":"Oscar Wilde","personWikipediaUrl":"https://en.wikipedia.org/wiki/Oscar_Wilde","sourceTitle":"Miscellaneous Aphorisms","sourceUrl":"https://www.gutenberg.org/cache/epub/33979/pg33979.txt","sourceSha256":"b2f26f9cca110780f4fcfe08aa5159f31306e6fe66c27d474dfdc5e95e40dfbf"}',
  '{"definitionId":"read-the-warmth-of-other-suns","slot":2,"id":"historic-quotation/q-0589ba450157864aca52ba4537e92e9b","text":"Virtue, like a strong and hardy plant, will root when it can find an ingenuous nature and a mind not averse to labour.","person":"Plutarch","personWikipediaUrl":"https://en.wikipedia.org/wiki/Plutarch","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"read-spqr","slot":1,"id":"historic-quotation/q-7ce75a5d9ddc310a2f54094e8174416f","text":"A true benevolence knows the reason of its gifts.","person":"Publilius Syrus","personWikipediaUrl":"https://en.wikipedia.org/wiki/Publilius_Syrus","sourceTitle":"The Moral Sayings of Publius Syrus, a Roman Slave","sourceUrl":"https://en.wikisource.org/wiki/The_Moral_Sayings_of_Publius_Syrus%2C_A_Roman_Slave?printable=yes","sourceSha256":"155e6832121547772bf11fa24feb36883a3b392cdb09101183929fe15cc43973"}',
  '{"definitionId":"read-spqr","slot":2,"id":"historic-quotation/q-221594c45596e84f99ca2639bf2c8d89","text":"Life is given to us, we earn it by giving it.","person":"Rabindranath Tagore","personWikipediaUrl":"https://en.wikipedia.org/wiki/Rabindranath_Tagore","sourceTitle":"Stray Birds","sourceUrl":"https://www.gutenberg.org/cache/epub/6524/pg6524.txt","sourceSha256":"b8ad6f2827cb2b8496e386e583c93d6a4ce2525a24887d03ca361f5253eb5f9f"}',
  '{"definitionId":"read-a-brief-history-of-time","slot":1,"id":"historic-quotation/q-c89570042f952f1f325f8b0a25ef9cab","text":"As to what we call the masses, and common men — there are no common men.","person":"Ralph Waldo Emerson","personWikipediaUrl":"https://en.wikipedia.org/wiki/Ralph_Waldo_Emerson","sourceTitle":"The Wisdom of Ralph Waldo Emerson: Being Extracts from His Prose and Verse","sourceUrl":"https://archive.org/download/wisdomralphwald00parkgoog/wisdomralphwald00parkgoog_djvu.txt","sourceSha256":"325b25b72d66c0d6cff42367ad492b26cab54375e8eaaa6e2e51830e0f639a00"}',
  '{"definitionId":"read-a-brief-history-of-time","slot":2,"id":"historic-quotation/q-b22713b70c14c5c47322083fa27a7b7a","text":"There never was any heart truly great and generous that was not also tender and compassionate.","person":"Robert South","personWikipediaUrl":"https://en.wikipedia.org/wiki/Robert_South_(priest)","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"read-the-selfish-gene","slot":1,"id":"historic-quotation/q-25b7eb0f3bab5009d64bb804b002737a","text":"What is read twice is commonly better remembered than what is transcribed.","person":"Samuel Johnson","personWikipediaUrl":"https://en.wikipedia.org/wiki/Samuel_Johnson","sourceTitle":"Familiar Quotations","sourceUrl":"https://www.gutenberg.org/cache/epub/27889/pg27889.txt","sourceSha256":"28da04fea3f40e0810b63102e30010479728230af8436f3f83ebdf8b32b9f1fb"}',
  '{"definitionId":"read-the-selfish-gene","slot":2,"id":"historic-quotation/q-cf88d1ef08a6bbfb8478b981e66e7934","text":"There are two freedoms,--the false, where a man is free to do what he likes; the true, where a man is free to do what he ought.","person":"Charles Kingsley","personWikipediaUrl":"https://en.wikipedia.org/wiki/Charles_Kingsley","sourceTitle":"Many Thoughts of Many Minds","sourceUrl":"https://www.gutenberg.org/cache/epub/17112/pg17112.txt","sourceSha256":"54ff4ba19eb9dd7b367d8f9893dd07fad81e5ce8b71bd5db5b38676c68221c21"}',
  '{"definitionId":"read-the-gene","slot":1,"id":"historic-quotation/q-48cb9653ea3f586bfc973703401a9f98","text":"The ideal of friendship is to feel as one while remaining two.","person":"Sophie Swetchine","personWikipediaUrl":"https://en.wikipedia.org/wiki/Sophie_Swetchine","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"read-the-gene","slot":2,"id":"historic-quotation/q-ec4721e4703bdb8cff486591e6ff426e","text":"The real object of the drama is the exhibition of human character.","person":"Thomas Babington Macaulay","personWikipediaUrl":"https://en.wikipedia.org/wiki/Thomas_Babington_Macaulay,_1st_Baron_Macaulay","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"read-the-emperor-of-all-maladies","slot":1,"id":"historic-quotation/q-bafed50257f3f3c34fdace896c0c70c1","text":"The end of man is an action, not a thought, though it were the noblest.","person":"Thomas Carlyle","personWikipediaUrl":"https://en.wikipedia.org/wiki/Thomas_Carlyle","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"read-the-emperor-of-all-maladies","slot":2,"id":"historic-quotation/q-0fa68db695330927741a4dacb7e5c441","text":"As a musician might say, every natural group of flowering plants is a sort of visible fugue, wandering about a central theme which is never forsaken, however it may, momentarily, cease to be apparent.","person":"Thomas Henry Huxley","personWikipediaUrl":"https://en.wikipedia.org/wiki/Thomas_Henry_Huxley","sourceTitle":"Aphorisms and Reflections from the works of T. H. Huxley","sourceUrl":"https://www.gutenberg.org/cache/epub/35584/pg35584.txt","sourceSha256":"d43f042e4a0275e8903349a3fcfa4f5b992bcc186c536da1dd146391beb8e90b"}',
  '{"definitionId":"read-the-sixth-extinction","slot":1,"id":"historic-quotation/q-e8e18f86291e164eed582de5d9b3485e","text":"Above the cloud with its shadow is the star with its light.","person":"Victor Hugo","personWikipediaUrl":"https://en.wikipedia.org/wiki/Victor_Hugo","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"read-the-sixth-extinction","slot":2,"id":"historic-quotation/q-9d55fc9a415013ef6ecfeaf2c76d5da3","text":"There are no real pleasures without real needs.","person":"Voltaire","personWikipediaUrl":"https://en.wikipedia.org/wiki/Voltaire","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"read-cosmos","slot":1,"id":"historic-quotation/q-da491a3126599d24a5019af1683cccf2","text":"The willow which bends to the tempest often escapes better than the oak which resists it.","person":"Walter Scott","personWikipediaUrl":"https://en.wikipedia.org/wiki/Walter_Scott","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"read-cosmos","slot":2,"id":"historic-quotation/q-6d6b0f9b9e09272cb13cb9888495577b","text":"Some to the fascination of a name Surrender judgment hoodwink\'d.","person":"William Cowper","personWikipediaUrl":"https://en.wikipedia.org/wiki/William_Cowper","sourceTitle":"Familiar Quotations","sourceUrl":"https://www.gutenberg.org/cache/epub/27889/pg27889.txt","sourceSha256":"28da04fea3f40e0810b63102e30010479728230af8436f3f83ebdf8b32b9f1fb"}',
  '{"definitionId":"read-meditations","slot":1,"id":"historic-quotation/q-1483b122a37ca64ae353fdb917f191f2","text":"No greatness, no beauty, which does not come from truth","person":"William Dean Howells","personWikipediaUrl":"https://en.wikipedia.org/wiki/William_Dean_Howells","sourceTitle":"Widger\'s Quotations from the Project Gutenberg Editions of the Works of William Dean Howells","sourceUrl":"https://www.gutenberg.org/cache/epub/3483/pg3483.txt","sourceSha256":"5b190a7175e291dfd07d8ebcd78f596fa29e2b2127da71cad1d4bc81cbdc2a55"}',
  '{"definitionId":"read-meditations","slot":2,"id":"historic-quotation/q-72929ba9aeda94b1a28e69072ea88854","text":"True love is the parent of a noble humility.","person":"William Ellery Channing","personWikipediaUrl":"https://en.wikipedia.org/wiki/William_Ellery_Channing","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"read-the-republic","slot":1,"id":"historic-quotation/q-4503047eb5dc43d3488fbc7e2e132317","text":"Principle is a passion for truth.","person":"William Hazlitt","personWikipediaUrl":"https://en.wikipedia.org/wiki/William_Hazlitt","sourceTitle":"Pearls of Thought","sourceUrl":"https://www.gutenberg.org/cache/epub/26604/pg26604.txt","sourceSha256":"bd029a4490008a4ee6ad5738df5ba723c2ba850092f9e9042b32e0fe5540a2b6"}',
  '{"definitionId":"read-the-republic","slot":2,"id":"historic-quotation/q-e9f4764479b681cd6372716303f772f4","text":"How far that little candle throws its beams! So shines a good deed in a naughty world.","person":"William Shakespeare","personWikipediaUrl":"https://en.wikipedia.org/wiki/William_Shakespeare","sourceTitle":"Pearls of Thought","sourceUrl":"https://www.gutenberg.org/cache/epub/26604/pg26604.txt","sourceSha256":"bd029a4490008a4ee6ad5738df5ba723c2ba850092f9e9042b32e0fe5540a2b6"}',
  '{"definitionId":"read-mans-search-for-meaning","slot":1,"id":"historic-quotation/q-b9bc34b82321c9be469b6cee55184359","text":"The primal duties shine aloft, like stars; the charities that soothe, and heal, and bless, are scattered at the feet of man, like flowers.","person":"William Wordsworth","personWikipediaUrl":"https://en.wikipedia.org/wiki/William_Wordsworth","sourceTitle":"Pearls of Thought","sourceUrl":"https://www.gutenberg.org/cache/epub/26604/pg26604.txt","sourceSha256":"bd029a4490008a4ee6ad5738df5ba723c2ba850092f9e9042b32e0fe5540a2b6"}',
  '{"definitionId":"read-mans-search-for-meaning","slot":2,"id":"historic-quotation/q-5750b958c5a847594ff8039ea6a20d73","text":"Don\'t let joy carry you into excesses.","person":"Abraham Lincoln","personWikipediaUrl":"https://en.wikipedia.org/wiki/Abraham_Lincoln","sourceTitle":"The Lincoln Year Book: Axioms and Aphorisms from the Great Emancipator","sourceUrl":"https://www.gutenberg.org/cache/epub/39204/pg39204.txt","sourceSha256":"1b6a3cb3664183e06d932e706117f3ca6721875c9564315ed22fe81897e3b4a2"}',
  '{"definitionId":"read-the-myth-of-sisyphus","slot":1,"id":"historic-quotation/q-f565534f08f04d69dcee20e945a070f4","text":"Give assistance, not advice, in a crisis.","person":"Aesop","personWikipediaUrl":"https://en.wikipedia.org/wiki/Aesop","sourceTitle":"Aesop’s Fables: A New Translation (translated by V. S. Vernon Jones)","sourceUrl":"https://www.gutenberg.org/cache/epub/11339/pg11339.txt","sourceSha256":"0a2e7b971b00b76164071563e7e4bfa9cf962118ef67db9259020fc7c3b83602"}',
  '{"definitionId":"read-the-myth-of-sisyphus","slot":2,"id":"historic-quotation/q-290cd101b210d9cdbd1974e018f9f15f","text":"Oh, blest with temper whose unclouded ray Can make to-morrow cheerful as to-day!","person":"Alexander Pope","personWikipediaUrl":"https://en.wikipedia.org/wiki/Alexander_Pope","sourceTitle":"Familiar Quotations","sourceUrl":"https://www.gutenberg.org/cache/epub/27889/pg27889.txt","sourceSha256":"28da04fea3f40e0810b63102e30010479728230af8436f3f83ebdf8b32b9f1fb"}',
  '{"definitionId":"read-justice","slot":1,"id":"historic-quotation/q-0090d7f8f46e28e9ad2bbed7160830fb","text":"Let knowledge grow from more to more.","person":"Alfred, Lord Tennyson","personWikipediaUrl":"https://en.wikipedia.org/wiki/Alfred,_Lord_Tennyson","sourceTitle":"Familiar Quotations","sourceUrl":"https://www.gutenberg.org/cache/epub/27889/pg27889.txt","sourceSha256":"28da04fea3f40e0810b63102e30010479728230af8436f3f83ebdf8b32b9f1fb"}',
  '{"definitionId":"read-justice","slot":2,"id":"historic-quotation/q-946ce9c1501216b43c289b8581334b2e","text":"The richest minds need not large libraries.","person":"Amos Bronson Alcott","personWikipediaUrl":"https://en.wikipedia.org/wiki/Amos_Bronson_Alcott","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"read-nicomachean-ethics","slot":1,"id":"historic-quotation/q-b9fdda00b73094d3d51e6480b97899d1","text":"To free a man from error is to give, and not to take away.","person":"Arthur Schopenhauer","personWikipediaUrl":"https://en.wikipedia.org/wiki/Arthur_Schopenhauer","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"read-nicomachean-ethics","slot":2,"id":"historic-quotation/q-35c0682d3be61a436d79025af43694e7","text":"All blood is alike ancient.","person":"Benjamin Franklin","personWikipediaUrl":"https://en.wikipedia.org/wiki/Benjamin_Franklin","sourceTitle":"The Prefaces, Proverbs, and Poems of Benjamin Franklin","sourceUrl":"https://archive.org/download/prefacesproverbs00franrich/prefacesproverbs00franrich_djvu.txt","sourceSha256":"715b4de9f83af6844e62aeb157828c60ce662982a7b7e66ff2106cca2eb51858"}',
  '{"definitionId":"read-the-innovators","slot":1,"id":"historic-quotation/q-f9ca4db7cf8cbf0390ee8672935681de","text":"We should be as careful of our words as of our actions, and as far from speaking ill as from doing ill.","person":"Cicero","personWikipediaUrl":"https://en.wikipedia.org/wiki/Cicero","sourceTitle":"Many Thoughts of Many Minds","sourceUrl":"https://www.gutenberg.org/cache/epub/17112/pg17112.txt","sourceSha256":"54ff4ba19eb9dd7b367d8f9893dd07fad81e5ce8b71bd5db5b38676c68221c21"}',
  '{"definitionId":"read-the-innovators","slot":2,"id":"historic-quotation/q-7febc8012df45f73d0491ffe12964c6e","text":"How lightly past hardship sits upon us!","person":"Charles Dudley Warner","personWikipediaUrl":"https://en.wikipedia.org/wiki/Charles_Dudley_Warner","sourceTitle":"Quotations from the Project Gutenberg Editions of the Works of Charles Dudley Warner","sourceUrl":"https://www.gutenberg.org/cache/epub/3471/pg3471.txt","sourceSha256":"29ea89b07f35cc0adf1d31a507a5bff5c564243cdc62d45fb26baf54a807d3fe"}',
  '{"definitionId":"read-the-design-of-everyday-things","slot":1,"id":"historic-quotation/q-dc08a1511f2e833bd0a1c0be50d49f4d","text":"The greatest events of an age are its best thoughts. It is the nature of thought to find its way into action.","person":"Christian Nestell Bovee","personWikipediaUrl":"https://en.wikipedia.org/wiki/Christian_Nestell_Bovee","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"read-the-design-of-everyday-things","slot":2,"id":"historic-quotation/q-ef6044eb920f2667d9671b2225c35fff","text":"To read without reflecting is like eating without digesting.","person":"Edmund Burke","personWikipediaUrl":"https://en.wikipedia.org/wiki/Edmund_Burke","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"read-the-pragmatic-programmer","slot":1,"id":"historic-quotation/q-9620c5053735f779f75b6833320f197f","text":"Earnest men never think in vain though their thoughts may be errors.","person":"Edward Bulwer-Lytton","personWikipediaUrl":"https://en.wikipedia.org/wiki/Edward_Bulwer-Lytton","sourceTitle":"Pearls of Thought","sourceUrl":"https://www.gutenberg.org/cache/epub/26604/pg26604.txt","sourceSha256":"bd029a4490008a4ee6ad5738df5ba723c2ba850092f9e9042b32e0fe5540a2b6"}',
  '{"definitionId":"read-the-pragmatic-programmer","slot":2,"id":"historic-quotation/q-55ca746c31de736fb632ba9bb8e570e8","text":"Virtue is like a rich stone,--best plain set.","person":"Francis Bacon","personWikipediaUrl":"https://en.wikipedia.org/wiki/Francis_Bacon","sourceTitle":"Familiar Quotations","sourceUrl":"https://www.gutenberg.org/cache/epub/27889/pg27889.txt","sourceSha256":"28da04fea3f40e0810b63102e30010479728230af8436f3f83ebdf8b32b9f1fb"}',
  '{"definitionId":"read-code","slot":1,"id":"historic-quotation/q-5b3d746acf2a8cc02d1d28ebba8bdcb8","text":"There occur cases in human life when it is wisdom not to be too wise.","person":"Friedrich Schiller","personWikipediaUrl":"https://en.wikipedia.org/wiki/Friedrich_Schiller","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"read-code","slot":2,"id":"historic-quotation/q-80f47630c0821540b1e1ea0e8395ddf8","text":"The only failure a man ought to fear is failure in cleaving to the purpose he sees to be best.","person":"George Eliot","personWikipediaUrl":"https://en.wikipedia.org/wiki/George_Eliot","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"read-algorithms-to-live-by","slot":1,"id":"historic-quotation/q-57b913736b99dd5d8409f8ac4d006719","text":"To know how to suggest is the great art of teaching.","person":"Henri-Frédéric Amiel","personWikipediaUrl":"https://en.wikipedia.org/wiki/Henri-Fr%C3%A9d%C3%A9ric_Amiel","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"read-algorithms-to-live-by","slot":2,"id":"historic-quotation/q-eb20f9b04650f4b2b036c53e3e623597","text":"To maintain one\'s self on this earth is not a hardship, but a pastime, if we would live simply and wisely.","person":"Henry David Thoreau","personWikipediaUrl":"https://en.wikipedia.org/wiki/Henry_David_Thoreau","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"read-the-phoenix-project","slot":1,"id":"historic-quotation/q-0f2e74462376b0484632f8f9567572c5","text":"Many beauties in art come by accident, that are preserved by choice.","person":"Henry Fuseli","personWikipediaUrl":"https://en.wikipedia.org/wiki/Henry_Fuseli","sourceTitle":"The Life and Writings of Henry Fuseli, Volume 3: Aphorisms, Chiefly Relative to the Fine Arts","sourceUrl":"https://www.gutenberg.org/cache/epub/40474/pg40474.txt","sourceSha256":"0c3311df36f322386e02996cf5a17ecaf97f021d721ddc286ea66f7ecfa03fea"}',
  '{"definitionId":"read-the-phoenix-project","slot":2,"id":"historic-quotation/q-1a413021a663fc2b1ca2c4c850e495f8","text":"It is difficult to know at what moment love begins; it is less difficult to know that it has begun.","person":"Henry Wadsworth Longfellow","personWikipediaUrl":"https://en.wikipedia.org/wiki/Henry_Wadsworth_Longfellow","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"read-chip-war","slot":1,"id":"historic-quotation/q-fc0ad6eb7be1c89065faac2431f6c6d1","text":"The first hour of the morning is the rudder of the day.","person":"Henry Ward Beecher","personWikipediaUrl":"https://en.wikipedia.org/wiki/Henry_Ward_Beecher","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"read-chip-war","slot":2,"id":"historic-quotation/q-f83cf9621c96833fe5dccc71dbe03ece","text":"To educate the intelligence is to enlarge the horizon of its desires and wants.","person":"James Russell Lowell","personWikipediaUrl":"https://en.wikipedia.org/wiki/James_Russell_Lowell","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"read-dune","slot":1,"id":"historic-quotation/q-6245090fe5b82d0b6c6f3d1db4db5fcd","text":"Joy descends gently upon us like the evening dew, and does not patter down like a hailstorm.","person":"Jean Paul","personWikipediaUrl":"https://en.wikipedia.org/wiki/Jean_Paul","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"read-dune","slot":2,"id":"historic-quotation/q-e06fa4c967d454de04d57e2e226bdd71","text":"We ought not to teach children the sciences, but to give them a taste for them.","person":"Jean-Jacques Rousseau","personWikipediaUrl":"https://en.wikipedia.org/wiki/Jean-Jacques_Rousseau","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"read-the-three-body-problem","slot":1,"id":"historic-quotation/q-12def3a748f1f01d2cbb9cd0ce3c7d03","text":"Happy the man who early learns the difference between his wishes and his powers.","person":"Johann Wolfgang von Goethe","personWikipediaUrl":"https://en.wikipedia.org/wiki/Johann_Wolfgang_von_Goethe","sourceTitle":"Book of Wise Sayings","sourceUrl":"https://www.gutenberg.org/cache/epub/21130/pg21130.txt","sourceSha256":"241fc6dd48bde0eaa24c2335184f566962f6a90e4b94a971b70d9600598a7fae"}',
  '{"definitionId":"read-the-three-body-problem","slot":2,"id":"historic-quotation/q-1125973aabfa6ec72cf3e5751e651034","text":"Time will run back and fetch the age of gold.","person":"John Milton","personWikipediaUrl":"https://en.wikipedia.org/wiki/John_Milton","sourceTitle":"Familiar Quotations","sourceUrl":"https://www.gutenberg.org/cache/epub/27889/pg27889.txt","sourceSha256":"28da04fea3f40e0810b63102e30010479728230af8436f3f83ebdf8b32b9f1fb"}',
  '{"definitionId":"read-foundation","slot":1,"id":"historic-quotation/q-3c21da6b9ee26e265ffbcebd3b94acb5","text":"The first, as indeed the last, nobility of education is in the rule over our thoughts.","person":"John Ruskin","personWikipediaUrl":"https://en.wikipedia.org/wiki/John_Ruskin","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"read-foundation","slot":2,"id":"historic-quotation/q-fe91e0ce142720831167bd52c7624969","text":"Truth takes the stamp of the souls it enters. It is rigorous and rough in arid souls, but tempers and softens itself in loving natures.","person":"Joseph Joubert","personWikipediaUrl":"https://en.wikipedia.org/wiki/Joseph_Joubert","sourceTitle":"Pearls of Thought","sourceUrl":"https://www.gutenberg.org/cache/epub/26604/pg26604.txt","sourceSha256":"bd029a4490008a4ee6ad5738df5ba723c2ba850092f9e9042b32e0fe5540a2b6"}',
  '{"definitionId":"read-neuromancer","slot":1,"id":"historic-quotation/q-a6babea11b64484426b8a69cd506c71c","text":"Wisdom is the daughter of experience.","person":"Leonardo da Vinci","personWikipediaUrl":"https://en.wikipedia.org/wiki/Leonardo_da_Vinci","sourceTitle":"Thoughts on Art and Life","sourceUrl":"https://www.gutenberg.org/cache/epub/29904/pg29904.txt","sourceSha256":"323f8893f03432a5b17a3f83ef698d1369a93dce41bdb16176653e85ba1a2c66"}',
  '{"definitionId":"read-neuromancer","slot":2,"id":"historic-quotation/q-241dc3227ebf67f75bca5f73f23ba766","text":"Good manners and good morals are sworn friends and firm allies.","person":"Cyrus Augustus Bartol","personWikipediaUrl":"https://en.wikipedia.org/wiki/Cyrus_Augustus_Bartol","sourceTitle":"Pearls of Thought","sourceUrl":"https://www.gutenberg.org/cache/epub/26604/pg26604.txt","sourceSha256":"bd029a4490008a4ee6ad5738df5ba723c2ba850092f9e9042b32e0fe5540a2b6"}',
  '{"definitionId":"read-the-left-hand-of-darkness","slot":1,"id":"historic-quotation/q-84bd182da7f713212493942ed7ec83f1","text":"Let not future things disturb thee, for thou wilt come to them, if it shall be necessary, having with thee the same reason which now thou usest for present things.","person":"Marcus Aurelius","personWikipediaUrl":"https://en.wikipedia.org/wiki/Marcus_Aurelius","sourceTitle":"Thoughts of Marcus Aurelius (George Long translation)","sourceUrl":"https://www.gutenberg.org/cache/epub/6920/pg6920.txt","sourceSha256":"8e7b98cf8b079ed5a5280560939240707e210e923751de4232bba007f70b7b4e"}',
  '{"definitionId":"read-the-left-hand-of-darkness","slot":2,"id":"historic-quotation/q-5de187a0f0d11163f2cff3e4be8308dc","text":"He who takes conscience for his guide, will not easily lose his way.","person":"Marguerite Gardiner, Countess of Blessington","personWikipediaUrl":"https://en.wikipedia.org/wiki/Marguerite_Gardiner,_Countess_of_Blessington","sourceTitle":"Desultory Thoughts and Reflections","sourceUrl":"https://www.gutenberg.org/cache/epub/75737/pg75737.txt","sourceSha256":"9261723ed516a715c977bee43c07f00e79fd6448012f2555b9ee5de340ed031a"}',
  '{"definitionId":"read-project-hail-mary","slot":1,"id":"historic-quotation/q-262ee998e9ef4e13bb55c21fe47ae12b","text":"Judge by the eye of reason, and not from common report","person":"Michel de Montaigne","personWikipediaUrl":"https://en.wikipedia.org/wiki/Michel_de_Montaigne","sourceTitle":"Widger\'s Quotations from the Project Gutenberg Editions of the Works of Montaigne","sourceUrl":"https://www.gutenberg.org/cache/epub/3661/pg3661.txt","sourceSha256":"8967e5fa2bd702eae39585cc9e7a0e248ad041ba38b3a20fe31265b579b4e40e"}',
  '{"definitionId":"read-project-hail-mary","slot":2,"id":"historic-quotation/q-e6bd000be7540b8c1b0465927b7ce024","text":"Truth may be stretched, but cannot be broken, and always gets above falsehood, as oil does above water.","person":"Miguel de Cervantes","personWikipediaUrl":"https://en.wikipedia.org/wiki/Miguel_de_Cervantes","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"read-the-remains-of-the-day","slot":1,"id":"historic-quotation/q-23814d5628bf4bf21ea07bf5d46a97e8","text":"Wisdom makes a slow defence against trouble, though at last a sure one.","person":"Oliver Goldsmith","personWikipediaUrl":"https://en.wikipedia.org/wiki/Oliver_Goldsmith","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"read-the-remains-of-the-day","slot":2,"id":"historic-quotation/q-034d07265e60e6f345108085cc1e844a","text":"Listen to what others say about subjects you have studied","person":"Oliver Wendell Holmes Sr.","personWikipediaUrl":"https://en.wikipedia.org/wiki/Oliver_Wendell_Holmes_Sr.","sourceTitle":"Widger\'s Quotations from the Project Gutenberg Editions of the Works of Oliver W. Holmes, Sr.","sourceUrl":"https://www.gutenberg.org/cache/epub/3493/pg3493.txt","sourceSha256":"5555b810cf767c77ffddf10242048512a01bac723f1f624a791e422819e66feb"}',
  '{"definitionId":"read-beloved","slot":1,"id":"historic-quotation/q-12235a10c13ce7a30d194e0770560c44","text":"The essence of thought, as the essence of life, is growth.","person":"Oscar Wilde","personWikipediaUrl":"https://en.wikipedia.org/wiki/Oscar_Wilde","sourceTitle":"Miscellaneous Aphorisms","sourceUrl":"https://www.gutenberg.org/cache/epub/33979/pg33979.txt","sourceSha256":"b2f26f9cca110780f4fcfe08aa5159f31306e6fe66c27d474dfdc5e95e40dfbf"}',
  '{"definitionId":"read-beloved","slot":2,"id":"historic-quotation/q-21f31e9dc25ebe507d9b90a978c29140","text":"An orator\'s life is more convincing than his eloquence.","person":"Publilius Syrus","personWikipediaUrl":"https://en.wikipedia.org/wiki/Publilius_Syrus","sourceTitle":"The Moral Sayings of Publius Syrus, a Roman Slave","sourceUrl":"https://en.wikisource.org/wiki/The_Moral_Sayings_of_Publius_Syrus%2C_A_Roman_Slave?printable=yes","sourceSha256":"155e6832121547772bf11fa24feb36883a3b392cdb09101183929fe15cc43973"}',
  '{"definitionId":"read-the-road","slot":1,"id":"historic-quotation/q-e5fd242722d453995a028ae26e52ccb9","text":"Not hammerstrokes, but dance of the water sings the pebbles into perfection.","person":"Rabindranath Tagore","personWikipediaUrl":"https://en.wikipedia.org/wiki/Rabindranath_Tagore","sourceTitle":"Stray Birds","sourceUrl":"https://www.gutenberg.org/cache/epub/6524/pg6524.txt","sourceSha256":"b8ad6f2827cb2b8496e386e583c93d6a4ce2525a24887d03ca361f5253eb5f9f"}',
  '{"definitionId":"read-the-road","slot":2,"id":"historic-quotation/q-2a496203dd4d535c5ba296233ea57903","text":"Be true to your own act, and congratulate yourself if you have done something strange and extravagant, and broken the monotony of a decorous age.","person":"Ralph Waldo Emerson","personWikipediaUrl":"https://en.wikipedia.org/wiki/Ralph_Waldo_Emerson","sourceTitle":"The Wisdom of Ralph Waldo Emerson: Being Extracts from His Prose and Verse","sourceUrl":"https://archive.org/download/wisdomralphwald00parkgoog/wisdomralphwald00parkgoog_djvu.txt","sourceSha256":"325b25b72d66c0d6cff42367ad492b26cab54375e8eaaa6e2e51830e0f639a00"}',
  '{"definitionId":"read-a-gentleman-in-moscow","slot":1,"id":"historic-quotation/q-e9bec06b879f495f896ddd49b9b13dc8","text":"Conscience is the sentinel of virtue.","person":"Samuel Johnson","personWikipediaUrl":"https://en.wikipedia.org/wiki/Samuel_Johnson","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"read-a-gentleman-in-moscow","slot":2,"id":"historic-quotation/q-67389398011c55f700b2e7ee920501b2","text":"In wonder all philosophy began; in wonder it ends; and admiration fills up the interspace.","person":"Samuel Taylor Coleridge","personWikipediaUrl":"https://en.wikipedia.org/wiki/Samuel_Taylor_Coleridge","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"read-the-kite-runner","slot":1,"id":"historic-quotation/q-4d87ccc80cf89c516881f24af3363157","text":"There are words which are worth as much as the best actions, for they contain the germ of them all.","person":"Sophie Swetchine","personWikipediaUrl":"https://en.wikipedia.org/wiki/Sophie_Swetchine","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"read-the-kite-runner","slot":2,"id":"historic-quotation/q-ef7ebb43c0983ce8f8c466b57d3d0260","text":"The kind of speech in a man betokens the kind of action you will get from him.","person":"Thomas Carlyle","personWikipediaUrl":"https://en.wikipedia.org/wiki/Thomas_Carlyle","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"read-pachinko","slot":1,"id":"historic-quotation/q-5991c9d1239ff1bcc1d54f046cf954ff","text":"Children work a greater metamorphosis in men than any other condition of life. They ripen one wonderfully and make life ten times better worth having than it was.","person":"Thomas Henry Huxley","personWikipediaUrl":"https://en.wikipedia.org/wiki/Thomas_Henry_Huxley","sourceTitle":"Aphorisms and Reflections from the works of T. H. Huxley","sourceUrl":"https://www.gutenberg.org/cache/epub/35584/pg35584.txt","sourceSha256":"d43f042e4a0275e8903349a3fcfa4f5b992bcc186c536da1dd146391beb8e90b"}',
  '{"definitionId":"read-pachinko","slot":2,"id":"historic-quotation/q-8cbd019cd99234d681987ff98e44ee65","text":"The ornament of a house is the friends who frequent it","person":"William Dean Howells","personWikipediaUrl":"https://en.wikipedia.org/wiki/William_Dean_Howells","sourceTitle":"Widger\'s Quotations from the Project Gutenberg Editions of the Works of William Dean Howells","sourceUrl":"https://www.gutenberg.org/cache/epub/3483/pg3483.txt","sourceSha256":"5b190a7175e291dfd07d8ebcd78f596fa29e2b2127da71cad1d4bc81cbdc2a55"}',
  '{"definitionId":"read-thinking-fast-and-slow","slot":1,"id":"historic-quotation/q-2fd98f9db1f553a9a8986b7c7192dbd2","text":"Great thoughts reduced to practice become great acts.","person":"William Hazlitt","personWikipediaUrl":"https://en.wikipedia.org/wiki/William_Hazlitt","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"read-thinking-fast-and-slow","slot":2,"id":"historic-quotation/q-5ca1d49d6378ee9e53761daab8c0cab8","text":"An honest tale speeds best, being plainly told.","person":"William Shakespeare","personWikipediaUrl":"https://en.wikipedia.org/wiki/William_Shakespeare","sourceTitle":"Familiar Quotations","sourceUrl":"https://www.gutenberg.org/cache/epub/27889/pg27889.txt","sourceSha256":"28da04fea3f40e0810b63102e30010479728230af8436f3f83ebdf8b32b9f1fb"}',
  '{"definitionId":"read-atomic-habits","slot":1,"id":"historic-quotation/q-2f266da3474a1c67c286b2f22edf3bd7","text":"Come forth into the light of things, Let Nature be your teacher.","person":"William Wordsworth","personWikipediaUrl":"https://en.wikipedia.org/wiki/William_Wordsworth","sourceTitle":"Familiar Quotations","sourceUrl":"https://www.gutenberg.org/cache/epub/27889/pg27889.txt","sourceSha256":"28da04fea3f40e0810b63102e30010479728230af8436f3f83ebdf8b32b9f1fb"}',
  '{"definitionId":"read-atomic-habits","slot":2,"id":"historic-quotation/q-0ada2e64bbf5a08fcaa291c25a6808a6","text":"Give us a little more light, and a little less noise.","person":"Abraham Lincoln","personWikipediaUrl":"https://en.wikipedia.org/wiki/Abraham_Lincoln","sourceTitle":"The Lincoln Year Book: Axioms and Aphorisms from the Great Emancipator","sourceUrl":"https://www.gutenberg.org/cache/epub/39204/pg39204.txt","sourceSha256":"1b6a3cb3664183e06d932e706117f3ca6721875c9564315ed22fe81897e3b4a2"}',
  '{"definitionId":"read-educated","slot":1,"id":"historic-quotation/q-566494ecbbb75d72adf4989c2b2d4c16","text":"One good turn deserves another.","person":"Aesop","personWikipediaUrl":"https://en.wikipedia.org/wiki/Aesop","sourceTitle":"Aesop’s Fables: A New Translation (translated by V. S. Vernon Jones)","sourceUrl":"https://www.gutenberg.org/cache/epub/11339/pg11339.txt","sourceSha256":"0a2e7b971b00b76164071563e7e4bfa9cf962118ef67db9259020fc7c3b83602"}',
  '{"definitionId":"read-educated","slot":2,"id":"historic-quotation/q-e8a68cd21ffbc783f6e8158a2b824080","text":"On life\'s vast ocean diversely we sail, Reason the card, but passion is the gale.","person":"Alexander Pope","personWikipediaUrl":"https://en.wikipedia.org/wiki/Alexander_Pope","sourceTitle":"Familiar Quotations","sourceUrl":"https://www.gutenberg.org/cache/epub/27889/pg27889.txt","sourceSha256":"28da04fea3f40e0810b63102e30010479728230af8436f3f83ebdf8b32b9f1fb"}',
  '{"definitionId":"read-kitchen-confidential","slot":1,"id":"historic-quotation/q-e338269e2edaad68ad720fc157ca3f91","text":"Let the great world spin forever down the ringing grooves of change.","person":"Alfred, Lord Tennyson","personWikipediaUrl":"https://en.wikipedia.org/wiki/Alfred,_Lord_Tennyson","sourceTitle":"Familiar Quotations","sourceUrl":"https://www.gutenberg.org/cache/epub/27889/pg27889.txt","sourceSha256":"28da04fea3f40e0810b63102e30010479728230af8436f3f83ebdf8b32b9f1fb"}',
  '{"definitionId":"read-kitchen-confidential","slot":2,"id":"historic-quotation/q-66ee9a143a7b0ac1992e82e830291e5b","text":"Who knows the mind has the key to all things else.","person":"Amos Bronson Alcott","personWikipediaUrl":"https://en.wikipedia.org/wiki/Amos_Bronson_Alcott","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"read-the-wager","slot":1,"id":"historic-quotation/q-f1fb4b0cc5547fb331131cabf24ec25e","text":"To get general ideas first and make particular observations last is to invert the process of education.","person":"Arthur Schopenhauer","personWikipediaUrl":"https://en.wikipedia.org/wiki/Arthur_Schopenhauer","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"read-the-wager","slot":2,"id":"historic-quotation/q-5b81fb421a1cd12ad11a4f26b156b7c5","text":"An honest Man will receive neither Money nor Praise that is not his due.","person":"Benjamin Franklin","personWikipediaUrl":"https://en.wikipedia.org/wiki/Benjamin_Franklin","sourceTitle":"The Prefaces, Proverbs, and Poems of Benjamin Franklin","sourceUrl":"https://archive.org/download/prefacesproverbs00franrich/prefacesproverbs00franrich_djvu.txt","sourceSha256":"715b4de9f83af6844e62aeb157828c60ce662982a7b7e66ff2106cca2eb51858"}',
  '{"definitionId":"read-the-anthropocene-reviewed","slot":1,"id":"historic-quotation/q-05fffea07c5e652bd06142c6a7fde240","text":"There are shades in all good pictures, but there are lights too, if we choose to contemplate them.","person":"Charles Dickens","personWikipediaUrl":"https://en.wikipedia.org/wiki/Charles_Dickens","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"read-the-anthropocene-reviewed","slot":2,"id":"historic-quotation/q-880ff5bea531bf601f1e4e81ba6061ae","text":"Longing is one thing and reason another","person":"Charles Dudley Warner","personWikipediaUrl":"https://en.wikipedia.org/wiki/Charles_Dudley_Warner","sourceTitle":"Quotations from the Project Gutenberg Editions of the Works of Charles Dudley Warner","sourceUrl":"https://www.gutenberg.org/cache/epub/3471/pg3471.txt","sourceSha256":"29ea89b07f35cc0adf1d31a507a5bff5c564243cdc62d45fb26baf54a807d3fe"}',
  '{"definitionId":"finished-bachelors-degree","slot":1,"id":"historic-quotation/q-c997078c1a692df58a9e0bf94761e225","text":"Time\'s best gift to us is serenity.","person":"Christian Nestell Bovee","personWikipediaUrl":"https://en.wikipedia.org/wiki/Christian_Nestell_Bovee","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"finished-bachelors-degree","slot":2,"id":"historic-quotation/q-ccdcff95e845231e0f4fb9077f37239c","text":"Toleration is good for all, or it is good for none.","person":"Edmund Burke","personWikipediaUrl":"https://en.wikipedia.org/wiki/Edmund_Burke","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"finished-masters-degree","slot":1,"id":"historic-quotation/q-772b9c3c64f57c18c029286155905d6c","text":"Life consists in the alternate process of learning and unlearning; but it is often wiser to unlearn than to learn.","person":"Edward Bulwer-Lytton","personWikipediaUrl":"https://en.wikipedia.org/wiki/Edward_Bulwer-Lytton","sourceTitle":"Pearls of Thought","sourceUrl":"https://www.gutenberg.org/cache/epub/26604/pg26604.txt","sourceSha256":"bd029a4490008a4ee6ad5738df5ba723c2ba850092f9e9042b32e0fe5540a2b6"}',
  '{"definitionId":"finished-masters-degree","slot":2,"id":"historic-quotation/q-e1d47b90f4dfa96d8043922c26148cc3","text":"A wise man will make more opportunities than he finds.","person":"Francis Bacon","personWikipediaUrl":"https://en.wikipedia.org/wiki/Francis_Bacon","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"earned-unl-degree","slot":1,"id":"historic-quotation/q-2837889b233729264e26c68e72b5380a","text":"Virtue may be stern, but never cruel, never inhuman.","person":"Friedrich Schiller","personWikipediaUrl":"https://en.wikipedia.org/wiki/Friedrich_Schiller","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
  '{"definitionId":"earned-unl-degree","slot":2,"id":"historic-quotation/q-bff5c6a938d1b33ece95df77dd3964df","text":"The reward of one duty is the power to fulfil another.","person":"George Eliot","personWikipediaUrl":"https://en.wikipedia.org/wiki/George_Eliot","sourceTitle":"Dictionary of Quotations from Ancient and Modern, English and Foreign Sources","sourceUrl":"https://www.gutenberg.org/cache/epub/48105/pg48105.txt","sourceSha256":"8257fd40eed29b7598836f8bee5993a4f7ae09fa404f367def35784049b70141"}',
];
